// @ts-check
// app-main.js — the main application body, extracted verbatim from the
// index.html inline <script> (PD: monolith → module, enables type-check + ESM).
// Loaded as a classic script at its original position (after the page body),
// so behaviour is identical to the inline block it replaced.
function g(id){return document.getElementById(id);}
function show(id){g(id).classList.remove("hidden");}
function hide(id){g(id).classList.add("hidden");}

// Scroll affordance: when a scrollable overlay has content extending beyond the
// viewport, toggle .has-overflow on the overlay so CSS can show a gradient+chevron
// on top of the sticky footer. .at-bottom hides the hint once the user reaches the end.
// Idempotent — safe to call after every render.
function attachScrollHint(ov){
  if(!ov) return;
  var update = function(){
    var clientH = ov.clientHeight;
    var scrollH = ov.scrollHeight;
    var top = ov.scrollTop;
    var hasOverflow = scrollH > clientH + 4;
    var atBottom = top + clientH >= scrollH - 8;
    ov.classList.toggle("has-overflow", hasOverflow);
    ov.classList.toggle("at-bottom", atBottom);
  };
  // Remove old listener if this overlay has been set up before
  if(ov._scrollHintBound){
    ov.removeEventListener("scroll", ov._scrollHintBound);
    window.removeEventListener("resize", ov._scrollHintBound);
  }
  ov._scrollHintBound = update;
  ov.addEventListener("scroll", update, {passive:true});
  window.addEventListener("resize", update);
  setTimeout(update, 50);
  setTimeout(update, 300);
}

