// Max-styled alert (replaces native alert which shows domain)
function maxAlert(message){
  var existing = document.getElementById("max-alert-overlay");
  if(existing) existing.remove();
  var ov = document.createElement("div");
  ov.id = "max-alert-overlay";
  ov.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:11000;display:flex;align-items:center;justify-content:center;padding:24px;";
  ov.innerHTML = '<div style="background:var(--c-bg);border-radius:12px;max-width:380px;width:100%;padding:22px 24px;box-shadow:0 12px 40px rgba(0,0,0,.25);">'
    +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">'
    +'<div style="width:28px;height:28px;border-radius:50%;background:var(--c-primary-top);color:var(--c-on-dark);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:13px;flex-shrink:0;">M</div>'
    +'<div style="font-size:13px;font-weight:700;">Max</div>'
    +'</div>'
    +'<div style="font-size:13px;color:#333;line-height:1.55;margin-bottom:16px;">'+message+'</div>'
    +'<button onclick="document.getElementById(\'max-alert-overlay\').remove()" style="width:100%;padding:9px;font-size:12px;font-weight:600;background:var(--c-primary-top);color:var(--c-on-dark);border:none;border-radius:6px;cursor:pointer;font-family:inherit;">OK</button>'
    +'</div>';
  ov.onclick = function(e){ if(e.target === ov) ov.remove(); };
  document.body.appendChild(ov);
}

var MAX_SYSTEM = "You are Max \u2014 the guide behind \"A Tourist's Guide to the Existential Universe.\" Your voice comes from five years of full-time travel across Europe, Central America, and the American West. You are not a tour operator. You are the traveler who stands in front of Klimt's Judith for forty minutes because you want to understand what he was actually thinking, not what the audio guide says he was thinking.\n\nYou work from specific historical facts \u2014 the date, the name, the decision that made a place what it is. You present those facts without commentary. The implication does its own work. You do not tell travelers what they will feel. You tell them what happened and you trust them.\n\nYour register shifts with purpose: light and observational when things are moving, something quieter when a place earns it. You know the difference between a place that matters and a place that has been told it matters. You are comfortable with uncertainty \u2014 sometimes \"I'd check locally\" is the most honest answer.\n\nHOW TO READ WHAT IS DRIVING A TRIP:\n\nEvery traveler begins with a sentence. That sentence reveals what you are actually working with.\n\n\"I've always wanted to\" \u2014 this is a stored intention, not a new idea. The destination already carries meaning. Your job is to surface the stories and history that will fulfill what has been waiting. Depth and resonance matter more than coverage.\n\n\"I want to\" \u2014 the experience comes first; the destination serves it. Lean toward logistics, sequencing, and the specific conditions that make participation possible. A hiker, a train traveler, a diver each need different things from the same place.\n\n\"I want to see\" \u2014 the traveler is responding to what a place holds. Some places draw through physical presence: landscape, light, scale. Others through what humans have made and left behind. Surface what is actually there, and why it is worth standing in front of.\n\n\"I need something different\" \u2014 this traveler is not choosing a destination yet. They are adjusting distance from their current life. Do not lead with candidates. First understand what they are moving away from and what register of difference they need. Then translate direction into places that sit at the right distance.\n\n\"We should go somewhere that\" \u2014 the group is shaping the trip. A destination that works for one person may fail another. Keep the relational constraints visible.\n\n\"It would be amazing to\" \u2014 there is a performative dimension present. Acknowledge what the trip signals as well as what it contains.\n\nFAMILIARITY SHAPES DEPTH:\n\nNot at all: orient before you go deep. The traveler needs the lay of the land before they can use detail. Do not assume prior knowledge.\n\nA passing understanding: skip basic orientation but do not assume fluency. The traveler knows some names and images but little of the underlying story. Fill in the frame as you go.\n\nQuite a bit: assume the basics are covered. Surface what even regular visitors miss, and what has changed.\n\nFOR PLACE STORIES: open with a specific fact, stay in 3\u20135 sentences, end with an open observation rather than a summary. For direct questions: be brief and concrete. For dig-deeper follow-ups: go further into the historical or cultural thread, don't repeat what you already said.\n\nNever say: hidden gem, vibrant, bustling, must-see, off the beaten path, iconic, charming, quaint, magical. Never tell the traveler how they will feel.";

// Round CI: cache LLM responses keyed on a hash of the request, so identical
// briefs produce identical plans. Anthropic's temperature=0 narrows variance
// but doesn't eliminate it across multiple LLM calls in a build flow; the
// cache makes the output truly deterministic for repeated runs of the same
// inputs. Stored in localStorage so reloads still hit the cache. Wipe with
// clearMaxCache() in the console; inspect with maxCacheStats().
//
// Round CI.1: TTL + prompt version. Entries expire after 30 days so
// "iconic" recommendations refresh within a season (a new museum, a new
// gondola line, a closure). _MAX_PROMPT_VERSION is baked into the cache
// key — bump it when shipping any prompt change you want to re-roll for
// everyone. Format: YYYY-MM-DD-roundLetters.
var _MAX_CACHE_KEY = "max-llm-cache-v1";
var _MAX_CACHE_LIMIT = 200; // cap entries; oldest evicted first
var _MAX_CACHE_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days
var _MAX_PROMPT_VERSION = "2026-04-28-CI2";
// Round CI.2: shared in-memory cache so concurrent callMax invocations
// don't clobber each other on save.
// Round CL.3: persistence moved from localStorage to IndexedDB.
// localStorage is one shared 5MB bucket across the entire origin —
// trip data fills it up and squeezes out the cache, triggering a
// QuotaExceededError feedback loop. IndexedDB has 50MB+ per origin
// and lives in its own bucket. _maxCacheMem mirrors what's in IDB so
// reads stay synchronous; writes fire-and-forget to IDB.
var _maxCacheMem = null;
var _MAX_IDB_NAME = "max-llm-cache";
var _MAX_IDB_STORE = "kv";
var _maxIdbReady = null; // Promise that resolves once initial load is done

function _maxIdbOpen(){
  return new Promise(function(resolve, reject){
    if (typeof indexedDB === "undefined") { reject(new Error("no IDB")); return; }
    var req = indexedDB.open(_MAX_IDB_NAME, 1);
    req.onupgradeneeded = function(){
      try { req.result.createObjectStore(_MAX_IDB_STORE); } catch(_){}
    };
    req.onsuccess = function(){ resolve(req.result); };
    req.onerror = function(){ reject(req.error); };
  });
}

function _maxIdbGet(key){
  return _maxIdbOpen().then(function(db){
    return new Promise(function(resolve, reject){
      try {
        var tx = db.transaction(_MAX_IDB_STORE, "readonly");
        var req = tx.objectStore(_MAX_IDB_STORE).get(key);
        req.onsuccess = function(){ resolve(req.result); };
        req.onerror = function(){ reject(req.error); };
      } catch(e){ reject(e); }
    });
  });
}

// PD.59b: enumerate keys in the kv store. Used by attachment GC.
function _maxIdbKeys(prefix){
  return _maxIdbOpen().then(function(db){
    return new Promise(function(resolve, reject){
      try {
        var tx = db.transaction(_MAX_IDB_STORE, "readonly");
        var req = tx.objectStore(_MAX_IDB_STORE).getAllKeys();
        req.onsuccess = function(){
          var keys = req.result || [];
          if (prefix) keys = keys.filter(function(k){ return String(k).indexOf(prefix) === 0; });
          resolve(keys);
        };
        req.onerror = function(){ reject(req.error); };
      } catch(e){ reject(e); }
    });
  });
}

function _maxIdbSet(key, value){
  return _maxIdbOpen().then(function(db){
    return new Promise(function(resolve, reject){
      try {
        var tx = db.transaction(_MAX_IDB_STORE, "readwrite");
        tx.objectStore(_MAX_IDB_STORE).put(value, key);
        tx.oncomplete = function(){ resolve(); };
        tx.onerror = function(){ reject(tx.error); };
      } catch(e){ reject(e); }
    });
  });
}

function _maxIdbDelete(key){
  return _maxIdbOpen().then(function(db){
    return new Promise(function(resolve, reject){
      try {
        var tx = db.transaction(_MAX_IDB_STORE, "readwrite");
        tx.objectStore(_MAX_IDB_STORE).delete(key);
        tx.oncomplete = function(){ resolve(); };
        tx.onerror = function(){ reject(tx.error); };
      } catch(e){ reject(e); }
    });
  });
}

// Initial load: fetch the persisted cache from IDB into _maxCacheMem. Also
// migrate any stale localStorage cache entry one-time so users who already
// had a cache there don't lose it.
_maxIdbReady = (async function(){
  try {
    var fromIdb = await _maxIdbGet(_MAX_CACHE_KEY);
    if (fromIdb && typeof fromIdb === "object") {
      _maxCacheMem = fromIdb;
      return;
    }
  } catch(_){ /* fall through */ }
  // Migration: pull from localStorage if present, then clear it
  try {
    var raw = localStorage.getItem(_MAX_CACHE_KEY);
    if (raw) {
      _maxCacheMem = JSON.parse(raw);
      localStorage.removeItem(_MAX_CACHE_KEY);
      // Push to IDB
      _maxIdbSet(_MAX_CACHE_KEY, _maxCacheMem).catch(function(){});
      console.log("[Max cache] migrated from localStorage to IndexedDB,", Object.keys(_maxCacheMem||{}).length, "entries");
      return;
    }
  } catch(_){}
  _maxCacheMem = {};
})();

function _maxCacheLoad(){
  // Synchronous read from in-memory mirror. The initial _maxIdbReady promise
  // populates _maxCacheMem on page load. If a callMax fires before that
  // resolves (rare — IDB load is fast), we return an empty object and the
  // first call after load will get a MISS that the IDB then catches up to.
  if (_maxCacheMem) return _maxCacheMem;
  _maxCacheMem = {};
  return _maxCacheMem;
}

function _maxCacheSave(c){
  // c is always === _maxCacheMem since callers got it from _maxCacheLoad.
  // Mutations have already happened in memory; we just need to persist.
  // Fire-and-forget; if IDB is broken or full (it shouldn't be), we still
  // have the data in memory for the rest of the session.
  _maxCacheMem = c;
  _maxIdbSet(_MAX_CACHE_KEY, _maxCacheMem).catch(function(e){
    console.warn("[Max cache] IDB save failed:", e);
  });
}
async function _maxCacheKey(messages, maxTokens){
  // SHA-256 of stringified payload. Same input produces the same key. The
  // model name and temperature are baked into the key so the cache
  // invalidates automatically if either changes.
  var payload = JSON.stringify({m:messages, t:maxTokens||1000, model:"sonnet-4-20250514", temp:0, v:_MAX_PROMPT_VERSION});
  if (window.crypto && window.crypto.subtle && window.crypto.subtle.digest) {
    try {
      var enc = new TextEncoder().encode(payload);
      var buf = await window.crypto.subtle.digest("SHA-256", enc);
      var arr = Array.from(new Uint8Array(buf));
      return arr.map(function(b){return b.toString(16).padStart(2,"0");}).join("");
    } catch(_){ /* fall through to raw key */ }
  }
  return "raw:" + payload;
}
// Round CL.4: also expose the cleanup as a console helper for debugging.
window.cleanupTrips = function(){ cleanupOrphanedTrips(); };
window.maxStorageStats = function(){
  var trips = 0, tripCount = 0, indexBytes = 0, otherBytes = 0;
  for (var k in localStorage) {
    var sz = (localStorage.getItem(k) || "").length;
    if (k.indexOf("max-trip-") === 0) { trips += sz; tripCount++; }
    else if (k === "max-trips-index") indexBytes = sz;
    else otherBytes += sz;
  }
  console.log("[Max storage]",
    "| trips:", tripCount, "(" + (trips/1024).toFixed(0) + "KB)",
    "| index:", (indexBytes/1024).toFixed(1) + "KB",
    "| other:", (otherBytes/1024).toFixed(1) + "KB",
    "| total:", ((trips+indexBytes+otherBytes)/1024).toFixed(0) + "KB / ~5120KB");
  return {trips: tripCount, tripBytes: trips, indexBytes: indexBytes, otherBytes: otherBytes};
};

window.clearMaxCache = function(){
  _maxCacheMem = {};
  try { localStorage.removeItem(_MAX_CACHE_KEY); } catch(_){}
  _maxIdbDelete(_MAX_CACHE_KEY).then(function(){
    console.log("[Max cache] cleared (IDB + localStorage)");
  }).catch(function(e){
    console.warn("[Max cache] IDB clear failed:", e);
  });
};
window.maxCacheStats = function(){
  var c = _maxCacheLoad();
  var keys = Object.keys(c);
  var bytes = JSON.stringify(_maxCacheMem || {}).length;
  console.log("[Max cache] entries:", keys.length, "| ~bytes (in-mem):", bytes, "| keys (first 5):", keys.slice(0,5).map(function(k){return k.substring(0,8);}));
  return {entries: keys.length, bytes: bytes};
};


// ──────────────────────────────────────────────────────────────────────
// Round PD.68: deterministic prompt construction. The LLM cache keys
// off the prompt string verbatim — if two runs build the prompt with
// the same user inputs but the arrays (chips, interests, drivers,
// must-dos, etc.) are in different orders, the prompt text differs
// and the cache misses. The model is called at temperature=0 but
// still has minor variance run-to-run, so cache misses produce
// slightly different lists — the "sometimes Selfoss appears,
// sometimes not" symptom Neal hit while testing.
//
// Fix: every array that gets joined into a prompt goes through
// _canonArr first — trim, dedupe (case-insensitive), sort. Order
// is meaningless to the LLM but byte-stable across runs, so cache
// keys hit reliably.
// ──────────────────────────────────────────────────────────────────────
function _canonArr(arr){
  if (!Array.isArray(arr)) return [];
  var seen = {};
  var out = [];
  for (var i = 0; i < arr.length; i++) {
    var v = arr[i];
    if (v == null) continue;
    var s = String(v).trim();
    if (!s) continue;
    var k = s.toLowerCase();
    if (seen[k]) continue;
    seen[k] = true;
    out.push(s);
  }
  out.sort(function(a, b){
    var al = a.toLowerCase(), bl = b.toLowerCase();
    return al < bl ? -1 : al > bl ? 1 : 0;
  });
  return out;
}
if (typeof globalThis !== "undefined") globalThis._canonArr = _canonArr;

async function callMax(messages, maxTokens, timeoutMs, opts) {
  // v345: route through MaxSync's LLM proxy when the user is signed
  // in. The server holds the Anthropic API key — testers no longer
  // need to paste their own. Falls back to direct API + user-pasted
  // key when not signed in (legacy path; keeps local dev working).
  //
  // v353.7: opts.system overrides the default MAX_SYSTEM prompt
  // (used by the chat surface, which has its own context-aware
  // system prompt). opts.noCache bypasses the response cache —
  // chat messages should always be fresh, never a cached answer
  // from a prior session.
  opts = opts || {};
  var systemOverride = opts.system || null;
  var noCache = !!opts.noCache;
  // v353.7: chat-only BYOK. opts.useOwnKey forces the direct-API
  // path with the user's local _apiKey, bypassing the server proxy
  // even when signed in. The chat surface always passes this; other
  // features (picker, ICS, candidate cities, etc.) leave it
  // unset and ride on the shared server key. Cost split: operator
  // pays for bounded calls, user pays for unbounded chat.
  // Round NC.X: once the proxy has failed in this session, skip it
  // for subsequent calls. Without this, every callMax wastes 1-2s
  // hitting the dead proxy before falling back. The flag is cleared
  // only on a fresh reload — if the proxy comes back, the user
  // refreshes and we try it again.
  var useProxy = (typeof MaxSync !== "undefined" &&
                  typeof MaxSync.isSignedIn === "function" &&
                  MaxSync.isSignedIn() &&
                  !opts.useOwnKey &&
                  !window._maxProxyDown);
  if (opts.useOwnKey && !_apiKey) {
    throw new Error("Chat needs your Anthropic API key — open the ⇄ Sync modal to add one, or click 💬 Ask and follow the prompt.");
  }
  var headers = {"Content-Type": "application/json"};
  if (useProxy) {
    var token = "";
    try { token = localStorage.getItem("max-server-token") || ""; } catch(_){}
    headers["Authorization"] = "Bearer " + token;
  } else {
    if (_apiKey) {
      headers["x-api-key"] = _apiKey;
      headers["anthropic-version"] = "2023-06-01";
      headers["anthropic-dangerous-direct-browser-access"] = "true";
    }
    if(!_apiKey){throw new Error('No API key — sign in via the ⇄ button (preferred) or click 🔑 to use your own key');}
  }

  // Round CI: cache lookup. If we've seen this exact request before, return
  // the cached response. Determinism for repeated runs of the same brief.
  // Round CI.1: also check the entry hasn't expired past the TTL.
  // v353.7: noCache opt skips the cache entirely (used by the chat
  // surface — chat replies should always be fresh). The cache key
  // also incorporates the system override so a different prompt
  // doesn't pull a stale answer from a different request.
  var cacheKey = await _maxCacheKey(messages, maxTokens + ":" + (systemOverride ? "sys:" + systemOverride.slice(0, 200) : ""));
  // PD.375: SINGLE-FLIGHT. The console showed the same cache key
  // stored 8 times in 3 seconds — N callers issued the same prompt
  // concurrently, each missed the not-yet-written cache, and each
  // paid for its own LLM call. Identical in-flight prompts now share
  // ONE request; followers await the leader's promise.
  window._maxInFlight = window._maxInFlight || {};
  if (!noCache && window._maxInFlight[cacheKey]) {
    console.log("[Max cache] JOIN in-flight", cacheKey.substring(0, 8));
    return await window._maxInFlight[cacheKey];
  }
  var cache = _maxCacheLoad();
  if (!noCache && cache[cacheKey]) {
    var age = Date.now() - (cache[cacheKey].at || 0);
    if (age > _MAX_CACHE_TTL_MS) {
      console.log("[Max cache] EXPIRED (age " + Math.round(age/86400000) + "d)", cacheKey.substring(0,8));
      delete cache[cacheKey];
      _maxCacheSave(cache);
      // fall through to refetch
    } else {
      cache[cacheKey].lastUsed = Date.now();
      _maxCacheSave(cache);
      console.log("[Max cache] HIT (age " + Math.round(age/86400000) + "d)", cacheKey.substring(0,8));
      return cache[cacheKey].text;
    }
  }

  // PD.375: register this request as the leader; followers with the
  // same key JOIN the promise above. Always settled (success or
  // error) in the wrapper below so a follower can never hang.
  var _flightDone = /** @type {any} */ (null);
  if (!noCache) {
    var _flightPromise = new Promise(function(res, rej){ _flightDone = { res: res, rej: rej }; });
    _flightPromise.catch(function(){}); // no unhandled-rejection noise when nobody joined
    window._maxInFlight[cacheKey] = _flightPromise;
  }
  try {
  var resp, data;
  var _llmAttempt = 0;
  // PD.481 (network reliability): retry loop around the LLM fetch so a
  // transient 429 (rate limit) / 529 (overloaded) backs off instead of
  // aborting Discovery/Enhance mid-plan. The in-flight/cache bookkeeping
  // lives OUTSIDE this loop (settled once at the end), so re-fetching here
  // is safe — it never re-registers or double-settles the in-flight promise.
  for (;;) {
  try {
    var fetchTimeout=new Promise(function(_,reject){setTimeout(function(){reject(new Error('API timeout'));},timeoutMs||25000);});
    // v345: choose endpoint based on auth path.
    var endpoint = useProxy
      ? (MaxSync.getServerUrl().replace(/\/+$/, '') + '/llm/messages')
      : "https://api.anthropic.com/v1/messages";
    resp = await Promise.race([fetch(endpoint, {
      method: "POST",
      headers: headers,
      body: JSON.stringify({
        model: "claude-sonnet-4-20250514",
        max_tokens: maxTokens||1000,
        // Round CH: temperature=0 for deterministic output. Was unset (default 1.0),
        // which caused different night totals on every run for the same brief.
        // v353.7: chat callers (opts.system override) want a more
        // natural-sounding reply, so they get a non-zero temperature.
        temperature: systemOverride ? 0.7 : 0,
        system: systemOverride || MAX_SYSTEM,
        messages: messages
      })
    }), fetchTimeout]);
    data = await resp.json();
  } catch(fetchErr) {
    // v353.2: don't prompt for an API key when the user is signed in
    // via proxy \u2014 they don't need one.
    //
    // Round NC.X: when the proxy is unreachable but the user has a
    // local API key, fall back to the direct path instead of just
    // throwing. This was the "sync server is down so the picker is
    // broken too" symptom \u2014 useProxy=true, fetch to the proxy fails,
    // user thinks Max is broken. Falling back to the direct path with
    // the local key keeps everything working until the proxy comes
    // back, with a one-line console note so the operator can see
    // what's happening.
    if (useProxy && _apiKey) {
      // Memoize the failure so subsequent calls in this session skip
      // the proxy attempt entirely and go straight to direct.
      window._maxProxyDown = true;
      console.warn("[Max] proxy unreachable (" + (fetchErr && fetchErr.message) + ") \u2014 falling back to direct API path with local key (further calls this session will skip proxy)");
      var directHeaders = {
        "Content-Type": "application/json",
        "x-api-key": _apiKey,
        "anthropic-version": "2023-06-01",
        "anthropic-dangerous-direct-browser-access": "true"
      };
      var directTimeout = new Promise(function(_, reject){ setTimeout(function(){ reject(new Error('API timeout')); }, timeoutMs || 25000); });
      try {
        resp = await Promise.race([fetch("https://api.anthropic.com/v1/messages", {
          method: "POST",
          headers: directHeaders,
          body: JSON.stringify({
            model: "claude-sonnet-4-20250514",
            max_tokens: maxTokens || 1000,
            temperature: systemOverride ? 0.7 : 0,
            system: systemOverride || MAX_SYSTEM,
            messages: messages
          })
        }), directTimeout]);
        data = await resp.json();
        // Successful fallback \u2014 let the rest of callMax handle the
        // response normally (cache write, return). We didn't break out
        // of the outer try/catch, so flow continues past line ~2836.
      } catch (directErr) {
        // Direct path also failed \u2014 surface the original error so the
        // user sees the actual root cause (CORS, DNS, network).
        throw fetchErr;
      }
    } else {
      if (!useProxy && !_apiKey && !_inIframe) {
        showApiKeyForm();
        throw new Error("API key required \u2014 enter your Anthropic API key in the form above.");
      }
      throw fetchErr;
    }
  }
  // PD.481: back off and retry on 429 (rate limit) / 529 (overloaded) /
  // 503. These are transient — the API is briefly busy, not broken — so a
  // hard fail here needlessly aborts a Discovery/Enhance run. Honor the
  // Retry-After header when present, else exponential backoff (1s, 2s, 4s),
  // up to 3 tries, then fall through to the normal error handling below.
  var _llmStatus = resp && resp.status;
  if ((_llmStatus === 429 || _llmStatus === 529 || _llmStatus === 503) && _llmAttempt < 3) {
    var _retryAfter = (resp.headers && typeof resp.headers.get === "function")
      ? parseInt(resp.headers.get("retry-after"), 10) : NaN;
    var _waitMs = (isFinite(_retryAfter) && _retryAfter > 0)
      ? Math.min(_retryAfter * 1000, 20000)
      : Math.min(1000 * Math.pow(2, _llmAttempt), 8000);
    console.warn("[Max PD.481] LLM " + _llmStatus + " (busy) — backing off " + _waitMs + "ms, retry " + (_llmAttempt + 1) + "/3");
    await new Promise(function(_r){ setTimeout(_r, _waitMs); });
    _llmAttempt++;
    continue;
  }
  break;
  } // end PD.481 retry loop
  if (data.error) {
    // v353.2: split the 401 handling per auth mode. Proxy users on
    // 401 mean their session token expired \u2014 clear it and route to
    // the sign-in modal, NOT the api-key form. BYOK users on 401
    // get the existing "key rejected, paste a fresh one" path.
    //
    // v355.1 (Playwright MA.4 fix): only pop the sign-in modal when
    // the user was ACTUALLY signed in. A 401 for someone who was
    // never signed in (typical of test envs and first-time visitors
    // who land on a screen that quietly fires a callMax) is not a
    // "session expired" event \u2014 it's just "not authenticated."
    // Surfacing the modal in that case interrupts unrelated UI
    // (was breaking itin-item.spec.js by intercepting pointer events
    // on adjacent buttons) and is the wrong message besides.
    if (useProxy && (data.error.type === "authentication_error" || resp.status === 401)) {
      var _wasSignedIn = (typeof MaxSync !== "undefined" && typeof MaxSync.isSignedIn === "function")
        ? !!MaxSync.isSignedIn() : false;
      if (_wasSignedIn) {
        // PD.424: do NOT destroy the session on the FIRST 401 \u2014 same
        // architectural flaw as the API-key bug (PD.421). A transient or
        // misclassified 401 (a momentary proxy/auth blip, an overload
        // surfaced as 401) was deleting the session token and signing the
        // user out \u2014 "I have to sign in multiple times." A persistent
        // credential must survive a transient error: only conclude the
        // session is genuinely expired after CONSECUTIVE 401s; the counter
        // resets on any successful call. A lone 401 throws a quiet,
        // retryable error and KEEPS the token.
        // PD.436: do NOT auto-pop the sign-in modal from a background LLM
        // call. Neal: "I still get a sign-in request, but when I close it,
        // it works anyway" -- the 401 was transient (the proxy is fine), and
        // shoving the modal over the screen on a blip is exactly the
        // intrusive behavior PD.339 removed for the API-key form. Surface a
        // quiet, one-shot toast and KEEP the session; the user re-signs-in
        // via the Sync button if a genuine expiry persists. We no longer
        // signOut / clear the token here at all -- a credential must survive
        // a transient error, and only an explicit user action ends a session.
        window._maxProxy401Count = (window._maxProxy401Count || 0) + 1;
        if (window._maxProxy401Count === 2) {
          try {
            if (typeof showSaveStatus === "function") {
              showSaveStatus("Sync had an auth hiccup — tap the Sync button to re-sign-in if it persists.", 6000);
            }
          } catch(_){}
        }
        throw new Error("Auth hiccup — your sign-in was kept; retry, and use the Sync button if it keeps failing.");
      }
      // Not signed in to begin with \u2014 throw a quieter error so callers
      // (refreshRestaurantSuggestions etc.) can degrade silently
      // rather than triggering the modal flow.
      throw new Error("Sign in to use this feature.");
    }
    if (!useProxy && !_apiKey && (data.error.type === "authentication_error" || resp.status === 401)) {
      // PD.339: do NOT auto-open the key modal. Background LLM calls
      // (secondary discovery, enrichment retries) kept popping it over
      // unrelated screens — the user hit Home and got a surprise
      // "Set Anthropic API key" dialog. Surface a quiet toast; the
      // 🔑 affordances are one tap away when the user wants them.
      try {
        if (typeof showSaveStatus === "function") showSaveStatus("Max needs an API key or sign-in for that — tap 🔑 when ready.", 5000);
      } catch(_){}
      throw new Error("API key required \u2014 tap \ud83d\udd11 to add your Anthropic API key.");
    }
    // PD.421: do NOT auto-DELETE the saved key on a 401. The old code
    // wiped max-api-key from localStorage on any 401 / authentication_error
    // \u2014 but a transient or misclassified 401 (a momentary auth blip, an
    // overload surfaced as 401, a single bad request) then destroyed a
    // VALID key, forcing the user to re-paste it ("my key disappeared
    // again"). Now we OPEN the entry form so the user can re-paste IF the
    // key is genuinely bad, but we keep the saved key in place so a one-off
    // 401 can't lose it. Re-pasting simply overwrites it.
    if (!useProxy && _apiKey && (data.error.type === "authentication_error" || resp.status === 401)) {
      if (typeof showApiKeyForm === "function") showApiKeyForm();
      throw new Error("Anthropic rejected that request (401). Your saved key was kept \u2014 if this keeps happening, paste a fresh copy from console.anthropic.com.");
    }
    throw new Error(data.error.message);
  }
  // PD.424: a successful response means the credential is fine — reset the
  // consecutive-401 tolerance counter so a later transient blip again gets
  // its grace before any sign-out.
  if (useProxy) window._maxProxy401Count = 0;
  var text = data.content[0].text;

  // Round CI: store in cache. Evict oldest by lastUsed if past the cap.
  cache[cacheKey] = {text: text, lastUsed: Date.now(), at: Date.now()};
  var cacheKeys = Object.keys(cache);
  if (cacheKeys.length > _MAX_CACHE_LIMIT) {
    cacheKeys.sort(function(a,b){return (cache[a].lastUsed||0) - (cache[b].lastUsed||0);});
    var toEvict = cacheKeys.length - _MAX_CACHE_LIMIT;
    for (var i = 0; i < toEvict; i++) delete cache[cacheKeys[i]];
  }
  _maxCacheSave(cache);
  console.log("[Max cache] MISS → stored", cacheKey.substring(0,8));

  if (_flightDone) { _flightDone.res(text); delete window._maxInFlight[cacheKey]; }
  return text;
  } catch (_flightErr) {
    // PD.375: settle the in-flight promise on EVERY exit so joined
    // followers get the same error instead of hanging.
    if (_flightDone) { _flightDone.rej(_flightErr); delete window._maxInFlight[cacheKey]; }
    throw _flightErr;
  }
}

// Round HF: inject callMax as the engine's "llm" service so the
// FQ verdict pipeline (now living in engine-trip.js) can call it
// without a hard reference to the inline-script function. Tests
// can re-inject a mock; production uses the real Anthropic-API
// wrapper above.
if (typeof MaxEngineTrip !== "undefined" && typeof MaxEngineTrip.injectService === "function") {
  MaxEngineTrip.injectService("llm", callMax);
}

// Round HT: inject 'llm' into the picker engine too, plus the
// city-data + geocode services that publishTrip's throttled-generate
// loop relies on. These are inline-script functions today; the engine
// asks for them by service name and falls back to window globals if
// no service is registered (defense in depth, in case load order
// shifts). Tests can inject stubs to avoid network.
if (typeof MaxEnginePicker !== "undefined" && typeof MaxEnginePicker.injectService === "function") {
  MaxEnginePicker.injectService("llm", callMax);
  if (typeof generateCityData === "function") {
    MaxEnginePicker.injectService("city-data", generateCityData);
  }
  if (typeof geocodeMissingCandidates === "function") {
    MaxEnginePicker.injectService("geocode-candidates", geocodeMissingCandidates);
  }
}

// ── Round FQ / FT (geo-affordance, day-trip mechanism) → trip-affordance.js (PD.457) ──

// ── File persistence ───────────────────────────────────────
var _fileHandle = null;
var _saveTimer  = null;
var _inIframe   = (window !== window.top);
var _hasFileAPI = !_inIframe && (typeof window !== "undefined") && ("showSaveFilePicker" in window);

function _persistTripRaw(id, json){
  // PD.475 (data integrity): route raw trip-envelope writes through
  // MaxDB.trip.writeRaw so the id==key assertion always runs (db.js) — a
  // mis-keyed envelope is the root of "trip lost / duplicated / reloaded
  // wrong". silent:true preserves the no-emit behaviour of the bare
  // localStorage.setItem calls these replace; falls back to a raw write
  // only if MaxDB is not wired yet (boot-order safety).
  try {
    if (typeof MaxDB !== "undefined" && MaxDB.trip && typeof MaxDB.trip.writeRaw === "function") {
      return MaxDB.trip.writeRaw(id, json, { silent: true });
    }
  } catch(_){}
  try { localStorage.setItem("max-trip-" + id, json); return true; } catch(_){ return false; }
}

function serializeTrip(){
  // PD.479 (network reliability): omit transient render caches from the
  // saved envelope. trip._osrmSegments holds OSRM "failed" sentinels from a
  // transient routing outage — persisting them POISONS the route: a segment
  // that failed once on bad signal would stay a straight line forever, even
  // after signal returns. These caches are rebuilt on demand and the
  // cache-signature invalidates them on any change, so they carry no value
  // in storage (and bloat it — road geometry is hundreds of points per
  // segment). Strip them here so every save/export starts routing fresh.
  var _transientKeys = { _osrmSegments:1, _osrmCacheSig:1, _osrmBatchInflight:1, _dtLoopFetched:1 };
  // P4.5: persist the decision LOG on the trip, so the user's keep/role/hub/leg
  // choices survive reload as data (not only as per-record _keep/_decided flags).
  // Stamped from the live working log (_tb._decisions) at the serialization
  // choke point — restored in _reconcileUserListedKeeps on the next load.
  try {
    if (typeof _tb !== "undefined" && _tb && _tb._decisions
        && typeof _tb._decisions.toJSON === "function" && trip) {
      if (!trip.brief || typeof trip.brief !== "object") trip.brief = {};
      trip.brief._decisionLog = _tb._decisions.toJSON();
    }
  } catch (_) {}
  return JSON.stringify(
    {trip:trip,activeDest:activeDest,destCtr:destCtr,sidCtr:sidCtr,bkCtr:bkCtr,activeDmSection:_activeDmSection},
    function(key, value){
      if (_transientKeys[key]) return undefined;
      // L2 (PD.479 class): trip._routingCache holds transport-option results
      // keyed by city pair, INCLUDING {_failed:true} sentinels from a transient
      // outage. Persisting a _failed entry latches "no transport options"
      // forever, even after the network recovers. Drop ONLY the failed entries
      // on save; keep successful results so we don't re-ask Max every reload.
      if (key === "_routingCache" && value && typeof value === "object") {
        var _rc = {};
        Object.keys(value).forEach(function(k){ var v = value[k]; if (!(v && v._failed)) _rc[k] = v; });
        return _rc;
      }
      return value;
    },
    2
  );
}

function restoreTrip(json){
  try{
    var d=JSON.parse(json);
    activeDest=d.activeDest;
    destCtr=d.destCtr||0; sidCtr=d.sidCtr||100; bkCtr=d.bkCtr||0;
    if(d.activeDmSection) _activeDmSection=d.activeDmSection;
    // ARCH Phase 3: route trip restore through TripStore so:
    //   - migrations run on legacy envelopes (backfills missing id, etc.)
    //   - global.trip and TripStore._trip stay in sync
    //   - tripChange fires so subscribers re-render against current data
    // The fallback (direct assignment + pendingActions init) covers the
    // race where this function is called before TripStore loaded.
    if (typeof TripStore !== "undefined" && d.trip) {
      TripStore.replace(d.trip);
    } else {
      trip=d.trip;
      if(!trip.pendingActions) trip.pendingActions=[];
    }
    // PD.468c: reconcile transit routes on load so trips SAVED before the
    // base-to-base change (PD.468) adopt the new hub-to-hub legs without the
    // user having to mutate the trip first — which is why a deploy + hard
    // refresh still showed the old place-to-place legs. syncTransitRoutes is
    // idempotent (no-op if already base-to-base) and re-homes any wayside
    // stops off superseded legs (PD.468b), so it's lossless.
    try {
      if (typeof MaxEngineTrip !== "undefined" && typeof MaxEngineTrip.syncTransitRoutes === "function" && window.trip) {
        MaxEngineTrip.syncTransitRoutes(window.trip);
      }
    } catch(_){}
    restoreTripUI();
  }catch(e){showSaveStatus("Couldn't read that file.",4000);console.error(e);}
}

function showSaveStatus(msg,duration){
  var el=g("save-status"); el.style.display="block"; el.textContent=msg;
  if(_saveTimer)clearTimeout(_saveTimer);
  _saveTimer=setTimeout(function(){el.style.display="none";},duration||3000);
}

function openTripFile(){
  var inp=document.getElementById("hs-trip-file-input");
  if(inp) inp.click();
}

function loadTripFile(input){
  var file=input.files&&input.files[0];
  if(!file) return;
  // v359.60.23: dispatch on extension. .json keeps the legacy
  // restore path (full trip envelope). .txt / .md route through
  // parsePlacesList → _buildStubTripFromPastedList, same path the
  // home-screen "Paste a list" uses — drops the file's content
  // into Research notes and auto-opens the modal so the user can
  // review before committing destinations. Falls back to JSON if
  // we can't tell from the name (e.g. no extension).
  var fname = (file.name || "").toLowerCase();
  var isText = /\.(txt|md)$/.test(fname);
  var reader=new FileReader();
  reader.onload=function(e){
    var raw = e.target.result;
    if (isText) {
      // v359.60.26: file-load now mints a STUB trip and routes through
      // the picker (candidate explorer) — each parsed place is run
      // through the LLM in batch to fill in country/coords/whyItFits/
      // role/tags/stayRange, then shown as candidates the user can
      // review + keep/reject + reorder. "Create a plan →" inside the
      // explorer commits the kept candidates into destinations. No
      // Research notes auto-open; the picker IS the review surface.
      // Paste flow uses the same function (see selectHomeOption).
      try {
        if (typeof parsePlacesList !== "function" || typeof _buildPickerFromPastedList !== "function") {
          throw new Error("Paste-list importer not available.");
        }
        var parsed = parsePlacesList(raw);
        if (!parsed.destinations.length) {
          throw new Error("No destinations found in the file. Each place should be on its own line, ideally under a section header like \"1. Overnight hubs\" or \"2. Sights\".");
        }
        _buildPickerFromPastedList(parsed, raw);
      } catch(err) {
        alert("Could not load list file: " + err.message);
      }
      input.value = "";
      return;
    }
    try{
      var data=JSON.parse(/** @type {any} */(raw));
      if(!data.trip||!data.trip.destinations) throw new Error("Not a valid trip file");
      trip=data.trip; activeDest=data.activeDest||null;
      if(!trip.pendingActions) trip.pendingActions=[];
      destCtr=data.destCtr||trip.destinations.length;
      sidCtr=data.sidCtr||100; bkCtr=data.bkCtr||0;
      if(data.activeDmSection) _activeDmSection=data.activeDmSection;
      // Save to localStorage with a new ID
      var newId="trip-"+Date.now();
      _currentTripId=newId;
      // PD.333 (audit C7/A2): the imported body gets the NEW id —
      // previously the envelope kept the exporter's old trip.id while
      // being stored under max-trip-<newId> (the id/key mismatch
      // class). And anchor TripStore so mutators act on THIS trip,
      // not a ghost from the previous session.
      trip.id = newId;
      if (typeof TripStore !== "undefined" && typeof TripStore.replace === "function") {
        try { TripStore.replace(trip); trip = TripStore.trip; } catch(_){}
      }
      // PD.327: route through single mutator (dedup by id, internal save).
      _upsertTripIndexEntry({id:newId,name:trip.name||"Imported trip",
        dateRange:trip.destinations.length?trip.destinations[0].dateFrom+" – "+trip.destinations[trip.destinations.length-1].dateTo:"",
        destCount:trip.destinations.length});
      _persistTripRaw(newId, JSON.stringify(data));
      // PD.330: file-loaded trips open at the trip overview. There's
      // no saved last-screen anymore — the URL is the source of truth
      // and an imported file doesn't carry one — so trip overview is
      // the canonical entry point (same as a card click).
      if (typeof MaxRoute !== "undefined") {
        MaxRoute.navigate({ screen: MaxRoute.SCREENS.TRIP, tripId: newId });
      }
      enterApp();
      showSaveStatus("Trip loaded: "+( trip.name||"Untitled trip"),4000);
    }catch(err){
      alert("Could not load trip file: "+err.message);
    }
    input.value=""; // reset so same file can be loaded again
  };
  reader.readAsText(file);
}

async function saveTrip(){
  var data=serializeTrip();
  var fname=(trip.name||"my-trip").replace(/[^a-z0-9\- ]/gi,"").trim().replace(/\s+/g,"-")||"my-trip";
  fname+=".json";
  if(_hasFileAPI){
    try{
      if(!_fileHandle){
        _fileHandle=await window.showSaveFilePicker({
          suggestedName:fname,
          types:[{description:"Trip file",accept:{"application/json":[".json"]}}]
        });
      }
      var w=await _fileHandle.createWritable();
      await w.write(data); await w.close();
      showSaveStatus("Saved \u2713 ("+trip.destinations.length+" destination"+(trip.destinations.length!==1?"s":"")+")",4000);
    }catch(e){
      if(e.name!=="AbortError"){showSaveStatus("Save failed: "+e.message,5000);console.error(e);}
    }
  } else {
    var blob=new Blob([data],{type:"application/json"});
    var url=URL.createObjectURL(blob);
    var a=document.createElement("a"); a.href=url; a.download=fname;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){URL.revokeObjectURL(url);},2000);
    showSaveStatus("Downloaded "+fname+" ("+trip.destinations.length+" destination"+(trip.destinations.length!==1?"s":"")+")",4000);
  }
}

