// PD.426 (map collapse #3, step 1): ONE marker factory. Every map surface
// drew pins with the identical sequence — style → html → icon → L.marker →
// bindTooltip → (bindPopup | on click) → push — duplicated at 8+ sites,
// each re-deriving the tooltip offset. This collapses that path into one
// call so the two renderers can't drift on how a pin is drawn.
//   spec: { lat, lng | latLng, role, styleCtx, label, badges, tooltip,
//           tooltipOpts, tooltipClassName, popupHtml, popupOpts, onClick,
//           className, zIndexOffset }
// Returns the L.marker, or null if coords are bad / the role is hidden.
MaxMapPin.draw = function(map, spec){
  if (!map || !spec || typeof L === "undefined") return null;
  var lat = spec.lat, lng = spec.lng;
  if (Array.isArray(spec.latLng)) { lat = spec.latLng[0]; lng = spec.latLng[1]; }
  if (typeof lat !== "number" || typeof lng !== "number" || !isFinite(lat) || !isFinite(lng)) return null;
  var style = MaxMapPin.style(spec.role || "maybe", spec.styleCtx || {});
  if (!style || style.hidden) return null;
  var html = MaxMapPin.html(style, { label: (spec.label != null ? spec.label : "") }, spec.badges || {});
  var icon = MaxMapPin.icon(html, style, spec.className ? { className: spec.className } : {});
  var mOpts = { icon: icon };
  if (typeof spec.zIndexOffset === "number") mOpts.zIndexOffset = spec.zIndexOffset;
  if (typeof spec.opacity === "number") mOpts.opacity = spec.opacity;
  var marker;
  try { marker = L.marker([lat, lng], mOpts).addTo(map); } catch(_){ return null; }
  if (spec.tooltip) {
    // Tooltip offset honors the icon's anchor (teardrop tip vs circle
    // center) so it clears the pin top regardless of shape — this was
    // re-derived at every call site (and inconsistently).
    var off = (style.anchor === "tip") ? [0, -style.height] : [0, -style.height / 2];
    try {
      marker.bindTooltip(spec.tooltip, spec.tooltipOpts || {
        permanent: false, direction: "top", offset: off,
        className: spec.tooltipClassName || ""
      });
    } catch(_){}
  }
  if (spec.popupHtml) {
    try { marker.bindPopup(spec.popupHtml, spec.popupOpts || { maxWidth: 260, autoPan: true, closeButton: true }); } catch(_){}
  }
  if (typeof spec.onClick === "function") {
    (function(mk){ mk.on("click", function(e){ try { spec.onClick(mk, e); } catch(_){} }); })(marker);
  }
  return marker;
};
// NC.8: swatch helper — returns an inline-block container with the
// pin shape for a given role, sized for use inside role-picker
// popovers + Discovery chips. Solves the "popover icon doesn't
// match the map pin" mismatch Neal flagged: the role popover used
// emoji (🛏 📍 🛣 👁) while the map used MaxMapPin's actual shapes
// (circle / circle+↻ / octagon / teardrop). Now both come from the
// same module.
//
// Sizing: nominal pin sizes (22 for stay/daytrip/onway, 24×30
// teardrop for see, 18 for maybe) render fine inline. Reject is
// hidden by MaxMapPin.style — for the popover we synthesize a small
// red ✕ circle so the row has a visible glyph.
MaxMapPin.swatch = function(role, opts){
  opts = opts || {};
  if (role === "reject") {
    var rs = opts.size || 18;
    return '<span style="display:inline-flex;align-items:center;justify-content:center;width:' + rs + 'px;height:' + rs + 'px;border-radius:50%;background:#c75348;color:#fff;font-size:' + Math.max(8, Math.round(rs*0.6)) + 'px;font-weight:700;flex-shrink:0;">&#10005;</span>';
  }
  var st = MaxMapPin.style(role, {});
  if (!st || st.hidden) return "";
  // Optional size override: scale width/height proportionally. Teardrop
  // preserves its 24:30 aspect; circle/octagon are 1:1.
  if (opts.size) {
    if (st.shape === "teardrop") {
      st.width  = opts.size * (24/30);
      st.height = opts.size;
    } else {
      st.width = st.height = opts.size;
    }
    // Keep glyph + stroke proportionate at very small sizes.
    if (opts.size < 16) {
      st.fontPx = Math.max(6, Math.round(opts.size * 0.45));
      st.strokeWidth = Math.max(1, Math.round(opts.size / 11));
    }
  }
  var html = MaxMapPin.html(st, { label: "" });
  // Container reserves the pin's visual footprint AND a little extra
  // room for asymmetric decorations: the legacy ↻ corner badge (still
  // possible if a future role uses roleGlyph) and the day-trip pin's
  // arrowhead. NC.9.1: arrow moved from 2 o'clock to 5 o'clock, so
  // the extra space follows — bottom + a touch on the right, no longer
  // top. Tip extends ~15-20% past the circle at the lower-right corner.
  // Vertical-align middle so the swatch sits flush with the role-label
  // text.
  var extraRight  = (st.shape === "daytripCircle") ? Math.round(st.width  * 0.15) : 0;
  var extraBottom = (st.shape === "daytripCircle") ? Math.round(st.height * 0.20) : 0;
  var badgeMargin = (st.roleGlyph && (!opts.size || opts.size >= 16)) ? 8 : 0;
  var w = st.width  + badgeMargin + extraRight;
  var h = st.height + (badgeMargin ? 4 : 0) + extraBottom;
  return '<span class="max-mappin-swatch" style="display:inline-flex;align-items:center;justify-content:center;width:' + w + 'px;height:' + h + 'px;flex-shrink:0;vertical-align:middle;overflow:visible;">' + html + '</span>';
};
