// settlements. When the user names a destination after such a feature
// (Mývatn, Vatnajökull, Snæfellsnes, Yellowstone), the centroid lands
// in the middle of water/ice/forest — useless as a destination pin.
// We snap to the nearest settlement instead via _refineCoordsToSettlement.
function _isWildernessNomType(cls, typ) {
  if (cls === "natural") return true; // lake, peak, bay, forest, glacier, island…
  if (cls === "boundary" && (typ === "national_park" || typ === "protected_area" || typ === "nature_reserve")) return true;
  if (cls === "place" && ["region","state","county","province","locality","island","islet","archipelago"].indexOf(typ) >= 0) return true;
  return false;
}

function _isSettlementNomType(cls, typ) {
  if (cls !== "place" && cls !== "boundary") return false;
  return ["city","town","village","hamlet","suburb","municipality","borough","quarter","neighbourhood"].indexOf(typ) >= 0;
}

function _sleepMs(ms){ return new Promise(function(r){ setTimeout(r, ms); }); }

// Given a feature centroid + its country, find the nearest named
// settlement (village/town/city/hamlet) and return its coordinates.
// Two Nominatim calls in the worst case (reverse + forward), each
// throttled to 1.1s to respect the 1 req/sec policy. Returns the
// original coords if no settlement can be identified.
async function _refineCoordsToSettlement(originalLat, originalLon, countryHint) {
  try {
    await _sleepMs(1100);
    var revUrl = 'https://nominatim.openstreetmap.org/reverse?format=json&zoom=14&addressdetails=1'
               + '&lat=' + originalLat + '&lon=' + originalLon;
    var rev = await fetch(revUrl, { headers: {'Accept-Language':'en'} });
    var rd = await rev.json();
    if (!rd) return null;
    var addr = rd.address || {};
    // If the reverse point itself is a settlement, use its coords.
    if (rd.lat && rd.lon && _isSettlementNomType(rd.class, rd.type)) {
      var slat = parseFloat(rd.lat), slon = parseFloat(rd.lon);
      if (isFinite(slat) && isFinite(slon)) return [slat, slon];
    }
    // Otherwise pull the most-specific settlement field from the
    // address object and forward-geocode that name to get its centroid.
    var settlement = addr.city || addr.town || addr.village || addr.hamlet || addr.suburb;
    if (!settlement) return null;
    await _sleepMs(1100);
    var country = addr.country || countryHint || "";
    var iso = _isoCodeForCountry(country);
    var fwUrl = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q='
              + encodeURIComponent(settlement + (country ? ", " + country : ""))
              + (iso ? '&countrycodes=' + iso : '');
    var fr = await fetch(fwUrl, { headers: {'Accept-Language':'en'} });
    var fres = await fr.json();
    if (fres && fres.length) {
      var flat = parseFloat(fres[0].lat), flon = parseFloat(fres[0].lon);
      if (isFinite(flat) && isFinite(flon)) return [flat, flon];
    }
    return null;
  } catch(e) {
    return null;
  }
}

// Country name → ISO 3166-1 alpha-2 code. Used to feed Nominatim's
// `countrycodes` parameter, which is a STRICT filter — without it,
// "Chillon, Switzerland" can still return Chillón in Spain because
// Nominatim's fuzzy matching ranks foreign matches above local ones.
var _countryToIso2 = {
  "switzerland":"ch","iceland":"is","italy":"it","france":"fr","germany":"de",
  "austria":"at","spain":"es","portugal":"pt","netherlands":"nl","belgium":"be",
  "luxembourg":"lu","united kingdom":"gb","uk":"gb","britain":"gb","england":"gb",
  "scotland":"gb","wales":"gb","ireland":"ie","norway":"no","sweden":"se",
  "finland":"fi","denmark":"dk","poland":"pl","czech republic":"cz","czechia":"cz",
  "slovakia":"sk","hungary":"hu","slovenia":"si","croatia":"hr","greece":"gr",
  "turkey":"tr","japan":"jp","china":"cn","south korea":"kr","korea":"kr",
  "thailand":"th","vietnam":"vn","cambodia":"kh","laos":"la","india":"in",
  "nepal":"np","bhutan":"bt","sri lanka":"lk","myanmar":"mm","mongolia":"mn",
  "russia":"ru","united states":"us","usa":"us","canada":"ca","mexico":"mx",
  "brazil":"br","argentina":"ar","chile":"cl","peru":"pe","colombia":"co",
  "ecuador":"ec","bolivia":"bo","uruguay":"uy","australia":"au","new zealand":"nz",
  "south africa":"za","morocco":"ma","egypt":"eg","kenya":"ke","tanzania":"tz",
  "uganda":"ug","ethiopia":"et","ghana":"gh","nigeria":"ng",
  "uae":"ae","united arab emirates":"ae","saudi arabia":"sa","israel":"il",
  "jordan":"jo","lebanon":"lb","iran":"ir","indonesia":"id","malaysia":"my",
  "singapore":"sg","philippines":"ph","taiwan":"tw"
};

function _isoCodeForCountry(name){
  if (!name) return "";
  var k = String(name).toLowerCase().trim().replace(/\.$/,"");
  return _countryToIso2[k] || "";
}

function ensureCoarseGeocode(place, onResolve, country){
  var key = (place||"").toLowerCase().trim();
  if (!key) return null;
  if (_coarseGeocode[key]) { if (onResolve) onResolve(_coarseGeocode[key]); return _coarseGeocode[key]; }
  if (_coarseGeocodeInFlight[key]) return null;
  _coarseGeocodeInFlight[key] = true;
  // R3: capture the requesting trip so a late-resolving geocode doesn't fire
  // its onResolve (which pins a coord onto the picker/map) after the user has
  // switched trips. The cache write below is kept (harmless + benefits a
  // revisit); only the surface callback is guarded against the clobber.
  var _reqTripId = (typeof trip !== "undefined" && trip && trip.id) ? trip.id : null;
  function _fireResolve(coords){
    var _cur = (typeof trip !== "undefined" && trip && trip.id) ? trip.id : null;
    if (_cur === _reqTripId && onResolve) onResolve(coords);
  }
  // Enqueue rather than fire immediately — avoids Nominatim rate-limit
  // cascades when the picker requests 20+ pins at once.
  _enqueueGeo(async function(){
    try {
      // Bias toward the trip's region when we have one — e.g. adding ", Italy" helps
      // disambiguate "Tirano" from unrelated places and keeps the result in the right country.
      var region = (typeof trip !== "undefined" && trip && trip.brief && trip.brief.region) ? trip.brief.region
                  : (typeof _tb !== "undefined" && _tb && _tb.region) ? _tb.region : "";
      var countryHint = country || region || "";
      var iso = _isoCodeForCountry(countryHint);
      var q = place + (countryHint ? ", " + countryHint : "");
      var url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(q)
              + (iso ? '&countrycodes=' + iso : '');
      var r = await fetch(url, { headers: {'Accept-Language':'en'} });
      var res = await r.json();
      if (res && res.length) {
        var hit = res[0];
        var lat = parseFloat(hit.lat), lon = parseFloat(hit.lon);
        if (isFinite(lat) && isFinite(lon)) {
          // v359.60.79: if Nominatim returned a natural-feature
          // centroid (lake, glacier, national park, etc.) instead of
          // a settlement, snap to the nearest named town/village so
          // the destination pin lands somewhere lodgeable. Mývatn
          // lake centroid → Reykjahlíð, Vatnajökull → Höfn, etc.
          if (_isWildernessNomType(hit.class, hit.type)) {
            var refined = await _refineCoordsToSettlement(lat, lon, countryHint);
            if (refined && Array.isArray(refined)) {
              console.log("[Max] refined " + place + " coord from " + lat.toFixed(4) + "," + lon.toFixed(4)
                + " (" + (hit.class||"") + "/" + (hit.type||"") + ") to nearest settlement "
                + refined[0].toFixed(4) + "," + refined[1].toFixed(4));
              lat = refined[0]; lon = refined[1];
            }
          }
          _coarseGeocode[key] = [lat, lon];
          _persistCoarseGeocode();
          _fireResolve(_coarseGeocode[key]);
        }
      } else if (iso) {
        // No result with strict country filter — retry without the filter.
        // This handles cases where the place name + country together fool
        // Nominatim's tokenizer (rare but happens).
        var r2 = await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='
          + encodeURIComponent(q), { headers: {'Accept-Language':'en'} });
        var res2 = await r2.json();
        if (res2 && res2.length) {
          var hit2 = res2[0];
          var lat2 = parseFloat(hit2.lat), lon2 = parseFloat(hit2.lon);
          if (isFinite(lat2) && isFinite(lon2)) {
            if (_isWildernessNomType(hit2.class, hit2.type)) {
              var refined2 = await _refineCoordsToSettlement(lat2, lon2, countryHint);
              if (refined2 && Array.isArray(refined2)) {
                lat2 = refined2[0]; lon2 = refined2[1];
              }
            }
            _coarseGeocode[key] = [lat2, lon2];
            _persistCoarseGeocode();
            _fireResolve(_coarseGeocode[key]);
          }
        }
      }
    } catch(e) { /* ignore */ }
    finally { delete _coarseGeocodeInFlight[key]; }
  });
  return null;
}

// getCityCenter moved to engine-trip.js (Round HR).

function getArrivalDeparture(dest){
  var locs=[];
  var destIdx=trip.destinations.indexOf(dest);
  // Arrival station = from previous destination's routing
  if(destIdx>0){
    var prev=trip.destinations[destIdx-1];
    var routing=getRouting(prev.place,dest.place);
    if(routing){
      var hub=getCityTransitHub(dest.place,"arrival");
      if(hub) locs.push({type:"arrival",name:hub.name,lat:hub.lat,lng:hub.lng,note:"Arrive from "+prev.place});
    }
  }
  // Departure station = to next destination
  if(destIdx<trip.destinations.length-1){
    var next=trip.destinations[destIdx+1];
    var routing2=getRouting(dest.place,next.place);
    if(routing2){
      var hub2=getCityTransitHub(dest.place,"departure");
      if(hub2) locs.push({type:"departure",name:hub2.name,lat:hub2.lat,lng:hub2.lng,note:"Depart to "+next.place});
    }
  }
  return locs;
}

function getCityTransitHub(place,direction){
  var p=place.toLowerCase();
  // Generated transitHub only — static table removed in favor of live generation.
  var gen=_generatedCityData[p];
  if(gen&&!gen.loading&&gen.transitHub&&gen.transitHub[direction]&&gen.transitHub[direction].lat)
    return gen.transitHub[direction];
  // Persisted on dest across reloads
  var dest=trip.destinations.find(function(d){return d.place.toLowerCase()===p;});
  if(dest&&dest.generatedTransitHub&&dest.generatedTransitHub[direction]&&dest.generatedTransitHub[direction].lat)
    return dest.generatedTransitHub[direction];
  return null;
}

function collectMapLocations(dest){
  var locs=[];
  // Guard missing fields from pre-schema data
  if(!dest.locations) dest.locations=[];
  if(!dest.hotelBookings) dest.hotelBookings=[];
  if(!dest.generalBookings) dest.generalBookings=[];

  // Sights from days
  dest.days.forEach(function(day){
    (day.items||day.sights||[]).filter(function(s){return s.type==="sight";}).forEach(function(s){
      var anchor=dest.locationAnchor||null;
      var center=anchor?[anchor.lat,anchor.lng]:getCityCenter(dest.place);
      // Use real geocoded coords if available in generated data
      var sLat=null,sLng=null;
      // Use coords stored on the item itself (set when added to day from Explore)
      if(s.lat&&s.lng){sLat=s.lat;sLng=s.lng;}
      else {
        var gen=_generatedCityData[dest.place.toLowerCase()];
        if(gen&&!gen.loading&&gen.sights){
          var match=gen.sights.find(function(gs){return gs.name===s.n;});
          if(match&&match.lat){sLat=match.lat;sLng=match.lng;}
        }
        // Also check dest.suggestions for coords
        if(!sLat&&dest.suggestions){
          var sm=dest.suggestions.find(function(sg){return sg.n===s.n&&sg.lat;});
          if(sm){sLat=sm.lat;sLng=sm.lng;}
        }
      }
      if(!center&&!sLat)return;
      locs.push({type:s.p==="must"?"sight-must":"sight-nice",name:s.n,
        lat:sLat||(center?center[0]+(Math.random()-.5)*.018:null),
        lng:sLng||(center?center[1]+(Math.random()-.5)*.022:null),
        note:s.done?"Visited \u2713":""});
    });
    // Restaurants from days
    (day.items||[]).filter(function(s){return s.type==="restaurant";}).forEach(function(s){
      var center=getCityCenter(dest.place);
      // Look up coords from restaurantSuggestions if available
      var rLat=null,rLng=null;
      // Use coords stored on the item itself (set when added to day)
      if(s.lat&&s.lng){rLat=s.lat;rLng=s.lng;}
      // Fallback: look up from suggestions pool
      else if(dest.restaurantSuggestions){
        var rm=dest.restaurantSuggestions.find(function(rs){return rs.n===s.n&&rs.lat;});
        if(rm){rLat=rm.lat;rLng=rm.lng;}
      }
      if(!center&&!rLat)return;
      locs.push({type:"restaurant",name:s.n,
        lat:rLat||(center?center[0]+(Math.random()-.5)*.014:null),
        lng:rLng||(center?center[1]+(Math.random()-.5)*.018:null),
        note:s.note||""});
    });
  });
  // Booked hotel
  var bookedHotel=dest.hotelBookings.find(function(b){return b.status==="booked";});
  if(bookedHotel){
    var _hc=getCityCenter(dest.place);
    var hlat=bookedHotel.lat||(_hc?_hc[0]+(Math.random()-.5)*.008:null);
    var hlng=bookedHotel.lng||(_hc?_hc[1]+(Math.random()-.5)*.010:null);
    if(hlat&&hlng) locs.push({type:"stay",name:bookedHotel.name,lat:hlat,lng:hlng,
      note:"Check-in "+fmtD(bookedHotel.checkIn)+(bookedHotel.confirmationNumber?" \u00b7 Conf: "+bookedHotel.confirmationNumber:"")});
  }
  // Arrival / departure
  getArrivalDeparture(dest).forEach(function(l){locs.push(l);});
  // Essentials (atm/grocery/tourist-info/pharmacy) now live on dest.suggestions,
  // populated by generateCityData and geocoded via Nominatim.
  var essentialTypes=["atm","bank","grocery","tourist-info","pharmacy"];
  var essentials=(dest.suggestions||[]).filter(function(s){
    return essentialTypes.indexOf(s.type)>-1 && s.lat && s.lng;
  }).map(function(s){
    return {type:s.type,name:s.n,lat:s.lat,lng:s.lng,note:s.note||""};
  });
  essentials.forEach(function(l){locs.push(l);});
  return locs;
}

function buildLayerGroups(locations){
  var groups={};
  MAP_LAYER_DEFS.forEach(function(d){
    if(d.id!=="all") groups[d.id]={g1:L.layerGroup(),g2:L.layerGroup()};
  });
  locations.forEach(function(loc){
    var layerKey=loc.type;
    if(layerKey==="sight-must"||layerKey==="sight-nice") layerKey="sights";
    if(layerKey==="arrival"||layerKey==="departure") layerKey="routing";
    if(!groups[layerKey])return;
    var popup=makePopup(loc.name,loc.type.replace("-"," "),loc.note);
    var icon=makeMapIcon(loc.type);
    L.marker([loc.lat,loc.lng],{icon:icon}).bindPopup(popup).addTo(groups[layerKey].g1);
    L.marker([loc.lat,loc.lng],{icon:icon}).bindPopup(popup).addTo(groups[layerKey].g2);
  });
  return groups;
}

function renderLayerToggles(){
  var bar=g("map-layer-bar"); bar.innerHTML="";
  MAP_LAYER_DEFS.forEach(function(d){
    var btn=document.createElement("button"); btn.className="map-layer-btn"+(_activeLayers[d.id]?" on":"");
    btn.id="mlb-"+d.id;
    var iconKey=LAYER_ICON_KEY[d.id];
    btn.innerHTML=(iconKey?makeLegendIcon(iconKey):"")+d.lbl;
    btn.onclick=function(){toggleMapLayer(d.id);};
    bar.appendChild(btn);
  });
}

function toggleMapLayer(id){
  if(id==="all"){
    var allOn=!_activeLayers.all;
    MAP_LAYER_DEFS.forEach(function(d){_activeLayers[d.id]=allOn;});
  } else {
    _activeLayers[id]=!_activeLayers[id];
    // Recompute all
    var allOn2=MAP_LAYER_DEFS.filter(function(d){return d.id!=="all";}).every(function(d){return _activeLayers[d.id];});
    _activeLayers.all=allOn2;
  }
  applyLayers();
  // Update buttons
  MAP_LAYER_DEFS.forEach(function(d){
    var btn=g("mlb-"+d.id); if(btn) btn.className="map-layer-btn"+(_activeLayers[d.id]?" on":"");
  });
}

function applyLayers(){
  if(!_map1||!_map2)return;
  Object.keys(_mapLayers).forEach(function(key){
    var lg=_mapLayers[key];
    if(_activeLayers[key]){_map1.addLayer(lg.g1);_map2.addLayer(lg.g2);}
    else{_map1.removeLayer(lg.g1);_map2.removeLayer(lg.g2);}
  });
}

function syncMaps(source,target){
  if(_syncFlag)return;
  _syncFlag=true;
  target.setView(source.getCenter(),source.getZoom(),{animate:false});
  _syncFlag=false;
}

function openMap(destId){
  var dest=getDest(destId); if(!dest)return;
  _mapDestId=destId;
  g("map-dest-lbl").textContent=dest.place+" \u00b7 "+fmtD(dest.dateFrom)+" \u2013 "+fmtD(dest.dateTo);
  _activeLayers={all:true,sights:true,stay:true,routing:true,atm:true,bank:true,grocery:true,"tourist-info":true,pharmacy:true,transit:true};
  renderLayerToggles();
  g("map-overlay").style.display="flex";
  // Leaflet needs the container visible before init
  setTimeout(function(){
    if(_map1){_map1.remove();_map1=null;} if(_map2){_map2.remove();_map2=null;}
    var center=getCityCenter(dest.place); var zoom=14;
    _map1=L.map("map1",{zoomControl:true}).setView(center,zoom);
    _map2=L.map("map2",{zoomControl:false}).setView(center,zoom);
    L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",{attribution:"\u00a9 Esri",maxZoom:19}).addTo(_map1);
    L.tileLayer("https://{s}.basemaps.cartocdn.com/light_only_labels/{z}/{x}/{y}{r}.png",{opacity:1.0,maxZoom:19}).addTo(_map1);
    L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",{attribution:"\u00a9 Esri",maxZoom:19}).addTo(_map2);
    L.tileLayer("https://{s}.basemaps.cartocdn.com/light_only_labels/{z}/{x}/{y}{r}.png",{opacity:1.0,maxZoom:19}).addTo(_map2);
    _map1.on("move",function(){syncMaps(_map1,_map2);}); _map1.on("zoom",function(){syncMaps(_map1,_map2);});
    _map2.on("move",function(){syncMaps(_map2,_map1);}); _map2.on("zoom",function(){syncMaps(_map2,_map1);});
    var locs=collectMapLocations(dest);
    _mapLayers=buildLayerGroups(locs);
    applyLayers();
  },80);
}

function closeMap(){
  if(_map1){_map1.remove();_map1=null;} if(_map2){_map2.remove();_map2=null;}
  g("map-overlay").style.display="none";
}

function setMobileMap(idx){
  g("map-panel-0").classList.toggle("map-hidden",idx!==0);
  g("map-panel-1").classList.toggle("map-hidden",idx!==1);
  g("mmb-0").className="map-mobile-btn"+(idx===0?" on":"");
  g("mmb-1").className="map-mobile-btn"+(idx===1?" on":"");
  // Invalidate the visible map's size
  setTimeout(function(){if(idx===0&&_map1)_map1.invalidateSize();if(idx===1&&_map2)_map2.invalidateSize();},50);
}
// ARCH Phase 6: _currentTripId is now a TripStore-backed property
// (see tripstore.js bottom-of-IIFE). Reads return TripStore.trip.id;
// writes route through TripStore.load / .replace / .unload so
// _currentTripId and TripStore can't diverge. The legacy `var
// _currentTripId = null` declaration is removed — TripStore.unload()
// covers the equivalent reset.
var _tripsIndex = [];

function loadTripsIndex(){
  if(_inIframe)return;
  try{var s=localStorage.getItem("max-trips-index");_tripsIndex=s?JSON.parse(s):[];}
  catch(e){_tripsIndex=[];}
  // Round CL.4: orphaned-trip GC. Before this, every test or aborted build
  // left a max-trip-{id} entry behind. Over weeks they accumulate and fill
  // the 5MB localStorage quota, causing trip saves to silently fail. Now
  // we sweep on every load: drop any max-trip-* whose id isn't in the
  // active index, plus drop empty shells (no destinations + no candidates)
  // that aren't the current trip.
  cleanupOrphanedTrips();
  // PD.250: IDB orphan sweep. Trips deleted before PD.250's MaxDB.trip.delete
  // routing still exist in IndexedDB (the original raw localStorage.removeItem
  // never touched IDB). hydrateTripIdbMirror() resurrects them on every page
  // load, which is what made deleted trips reappear after a hard refresh.
  // This pass waits for the mirror to populate, then deletes any trip ID
  // that isn't in _tripsIndex.
  if (typeof MaxDB !== "undefined" && MaxDB.trip
      && typeof MaxDB.trip.hydrated === "function"
      && typeof MaxDB.trip.listIds === "function"
      && typeof MaxDB.trip.delete === "function") {
    MaxDB.trip.hydrated().then(function () {
      try {
        // PD.333 (audit A3): signed-in users — server is the source of
        // truth; never reap locally. See cleanupOrphanedTrips.
        if (typeof MaxSync !== "undefined"
            && typeof MaxSync.isSignedIn === "function" && MaxSync.isSignedIn()) {
          return;
        }
        var indexedIds = {};
        _tripsIndex.forEach(function (t) { if (t && t.id) indexedIds[t.id] = true; });
        var allIds = MaxDB.trip.listIds();
        var reaped = 0;
        allIds.forEach(function (id) {
          if (id === _currentTripId) return; // never touch the active trip
          if (indexedIds[id]) return;        // still in the trips index
          try { MaxDB.trip.delete(id); reaped++; } catch (_) {}
        });
        if (reaped) console.log("[Max cleanup] reaped " + reaped + " IDB-only orphan trip(s)");
      } catch (e) {
        console.warn("[Max cleanup] IDB orphan sweep failed:", e && e.message);
      }
    });
  }
}

function cleanupOrphanedTrips(){
  if(_inIframe)return;
  try {
    var indexedIds = {};
    _tripsIndex.forEach(function(t){ if (t && t.id) indexedIds[t.id] = true; });
    // PD.331: the cleanup runs at BOOT, before selectTrip has set
    // _currentTripId — so "never touch the active trip" couldn't
    // protect the very trip the URL is about to open. A brand-new
    // trip sitting in Discovery (zero destinations; generation not
    // finished, so possibly zero candidates/placeActivities in the
    // envelope yet) matched the empty-shell heuristic and was
    // DELETED out from under the boot ("[Max cleanup] removed 1
    // trip(s) ... 1 empty shells" right before an empty trip view).
    // Also protect the trip referenced by the URL route.
    var _routeTripId = null;
    try {
      if (typeof MaxRoute !== "undefined") {
        var _clR = MaxRoute.parse();
        if (_clR && _clR.tripId) _routeTripId = _clR.tripId;
      }
    } catch(_){}
    var toDelete = [];
    var emptyShells = 0;
    var totalReclaimed = 0;
    var EMPTY_SHELL_MIN_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
    // PD.333 (audit A3): for SIGNED-IN users the server is the source
    // of truth and sync restores index + bodies on every boot — local
    // GC heuristics must not destroy data the server still has. While
    // signed in, this sweep only removes unparseable junk; orphan and
    // empty-shell heuristics are signed-out-only (local-only users
    // still need quota relief, with the PD.331 age + URL guards).
    var _gcSignedIn = false;
    try {
      _gcSignedIn = (typeof MaxSync !== "undefined"
        && typeof MaxSync.isSignedIn === "function" && MaxSync.isSignedIn());
    } catch(_){}
    for (var k in localStorage) {
      if (k.indexOf("max-trip-") !== 0) continue;
      var id = k.substring("max-trip-".length);
      if (id === _currentTripId) continue; // never touch the active trip
      if (_routeTripId && id === _routeTripId) continue; // PD.331: nor the trip the URL is opening
      var isOrphan = !indexedIds[id];
      if (_gcSignedIn) {
        // Signed in: only unparseable entries are deletable.
        var _parseOk = true;
        try { JSON.parse(localStorage.getItem(k)); } catch(_){ _parseOk = false; }
        if (_parseOk) continue;
        var _szJunk = (localStorage.getItem(k) || "").length;
        toDelete.push({key: k, id: id, size: _szJunk, reason: "unparseable"});
        totalReclaimed += _szJunk;
        continue;
      }
      var isEmpty = false;
      if (!isOrphan) {
        // Check for empty shell: parsed trip has zero destinations and zero candidates
        try {
          var parsed = JSON.parse(localStorage.getItem(k));
          var t = parsed && parsed.trip;
          // PD.73: a trip with no destinations AND no candidates AND no
          // placeActivities is a mint-then-abandon. placeActivities is
          // populated by the FIRST half of Discovery (must-dos LLM call);
          // candidates by the SECOND half. A trip caught mid-flow has
          // placeActivities but not candidates — that's substance and
          // must not be wiped.
          // PD.331: AND it must be OLD. A trip minted minutes ago whose
          // generation hasn't landed yet looks identical to an
          // abandoned shell — age is the only safe discriminator.
          // mint-then-abandon shells still get reaped, just a week on.
          if (t && (!t.destinations || t.destinations.length === 0)
                && (!t.candidates || t.candidates.length === 0)
                && (!t.placeActivities || t.placeActivities.length === 0)) {
            var _savedAt = (parsed && parsed.__saved__) ||
              (t.createdAt ? Date.parse(t.createdAt) : 0) || 0;
            if (_savedAt && (Date.now() - _savedAt) > EMPTY_SHELL_MIN_AGE_MS) {
              isEmpty = true;
              emptyShells++;
            }
          }
        } catch(_){ isOrphan = true; /* unparseable → treat as orphan */ }
      }
      if (isOrphan || isEmpty) {
        var sz = (localStorage.getItem(k) || "").length;
        toDelete.push({key: k, id: id, size: sz, reason: isOrphan ? "orphan" : "empty"});
        totalReclaimed += sz;
      }
    }
    toDelete.forEach(function(d){
      // PD.250: route through MaxDB.trip.delete to clear localStorage
      // AND IndexedDB. Raw localStorage.removeItem left IDB copies
      // behind, which hydrateTripIdbMirror() resurrects on next page
      // load — same root cause as the manual-delete leak.
      if (typeof MaxDB !== "undefined" && MaxDB.trip && typeof MaxDB.trip.delete === "function") {
        try { MaxDB.trip.delete(d.id); } catch(_) {
          try { localStorage.removeItem(d.key); } catch(__){}
        }
      } else {
        localStorage.removeItem(d.key);
      }
      // Also remove from index if it was a stale empty-shell that happens to
      // still be indexed.
      _tripsIndex = _tripsIndex.filter(function(t){ return t.id !== d.id; });
    });
    if (toDelete.length) {
      saveTripsIndex();
      console.log("[Max cleanup] removed " + toDelete.length + " trip(s) (" + (toDelete.length - emptyShells) + " orphans, " + emptyShells + " empty shells), freed " + (totalReclaimed/1024).toFixed(0) + "KB");
    }
  } catch(e) {
    console.warn("[Max cleanup] failed:", e);
  }
}

function saveTripsIndex(){
  if(_inIframe)return;
  try{localStorage.setItem("max-trips-index",JSON.stringify(_tripsIndex));}
  catch(e){}
}

// F6 (parallel-state): single door for appending a trips-index row from the
// duplicate / share-import flows. These intentionally read the PERSISTED index
// fresh and merge (NOT the in-memory _tripsIndex, which can be stale in these
// flows — using it could drop other trips), then the caller hard-reloads. This
// was duplicated as a raw read-push-setItem in two places; encapsulated here.
function _appendTripIndexEntry(entry){
  try {
    var idx = JSON.parse(localStorage.getItem("max-trips-index") || "[]");
    if (!Array.isArray(idx)) idx = [];
    idx.push(entry);
    localStorage.setItem("max-trips-index", JSON.stringify(idx));
  } catch (_) {}
}

// PD.327: single mutator for "add this trip to the trips index" across
// the 8 mint paths (paste-list build, sentence build, file import,
// publishTrip, _initialTripSave, etc.). Before this, every flow did a
// raw `_tripsIndex.push(entry)` with NO id-dedup. If two flows ran for
// the same intent — or if a single user action triggered multiple
// passes (race in autoSave + publishTrip + _initialTripSave) — the
// index ended up with multiple rows pointing at the same storage key.
// The home screen showed three "5:12am — Jun 6, 2026" cards because
// the index had three rows; the trip body itself was the same.
//
// Architecturally:
//   - Single point of write (this function) instead of 8.
//   - Dedup by id: if an entry with this id is already present, REPLACE
//     it (caller's fields win) — same semantics as MaxDB.index.upsert.
//   - Mirror to MaxDB.index so the localStorage backing and the
//     in-memory _tripsIndex stay coherent.
