function updateIndexEntry(){
  if(!_currentTripId)return;
  var entry=_tripsIndex.find(function(t){return t.id===_currentTripId;});
  if(!entry)return;
  entry.name=trip.name||"Untitled trip";
  entry.savedAt=new Date().toISOString();
  entry.destCount=trip.destinations.length;
  if(trip.destinations.length>0){
    entry.dateRange=fmtD(trip.destinations[0].dateFrom)
      +(trip.destinations.length>1?" \u2013 "+fmtD(trip.destinations[trip.destinations.length-1].dateTo):"");
    // Round CK.2: persist start/end dates + arrival/departure flight info
    // on the index entry so the home screen can show countdowns and flight
    // numbers without parsing the full trip JSON.
    entry.startDate = trip.destinations[0].dateFrom || "";
    entry.endDate = trip.destinations[trip.destinations.length - 1].dateTo || "";
    var ed = (trip.brief && trip.brief.entryDetails) || {};
    var xd = (trip.brief && trip.brief.exitDetails) || {};
    entry.entryDetails = (ed.carrier || ed.number || ed.time) ? {
      carrier: ed.carrier || "", number: ed.number || "", time: ed.time || ""
    } : null;
    entry.exitDetails = (xd.carrier || xd.number || xd.time) ? {
      carrier: xd.carrier || "", number: xd.number || "", time: xd.time || ""
    } : null;
    entry.entryCity = (trip.brief && trip.brief.entry) || "";
    entry.exitCity = (trip.brief && trip.brief.tbExit) || "";
  } else {
    entry.dateRange="";
    entry.startDate = "";
    entry.endDate = "";
    entry.entryDetails = null;
    entry.exitDetails = null;
  }
  saveTripsIndex();
}

function localSave(){
  if(_inIframe||!_currentTripId)return;
  // v353.5: shared-trip viewer never writes — the trip belongs to
  // someone else. The Duplicate button is the only way to materialize
  // edits. Bail before any storage / sync side-effect.
  if (typeof _readOnlyShare !== "undefined" && _readOnlyShare) return;
  try{
    updateIndexEntry();
    // v359.60.97: route through MaxDB.trip.writeRaw (silent mode) so
    // edits persist even when localStorage is full. Trips overflow to
    // IndexedDB automatically inside writeRaw — what used to be a
    // silent "QuotaExceededError, edit not persisted" warning is now
    // "trip wrote to IDB instead." The silent flag tells writeRaw
    // NOT to emit tripWritten; that event would cause engine-trip's
    // subscriber to re-parse the body and re-assign global.trip,
    // breaking any code holding refs into the live trip object (DOM
    // closures, hero-map markers, popup links). Local edits already
    // mutated global.trip in place and fired tripChange via
    // _emitTripMutation, so the UI is already up-to-date and the
    // event would just churn refs.
    //
    // v353.1: stamp the serialized envelope with __saved__ so
    // sync.js's pullAll() correctly identifies freshly-edited local
    // data as "newer than the last pull." Without this, the local
    // envelope's __saved__ stayed at the timestamp of the LAST PULL
    // — so during the 1.5s scheduleSave debounce window (between
    // localSave and the actual PUT to server), if a poll fired,
    // pullAll's `serverTimestamp > localTimestamp` check thought
    // the server was newer (because local timestamp was minutes
    // old) and clobbered the local edit. Setting __saved__ to now
    // makes the "is local newer?" comparison correct.
    var envelopeJson = serializeTrip();
    try {
      var env = JSON.parse(envelopeJson);
      env.__saved__ = Date.now();
      envelopeJson = JSON.stringify(env);
    } catch (_) { /* if parse fails, fall back to unstamped — better
                    than throwing out of localSave */ }
    var wrote = false;
    if (typeof MaxDB !== "undefined" && MaxDB.trip && typeof MaxDB.trip.writeRaw === "function") {
      wrote = MaxDB.trip.writeRaw(_currentTripId, envelopeJson, { silent: true });
    }
    if (!wrote) {
      // MaxDB not loaded yet, or writeRaw returned false. Best-effort
      // fallback to direct localStorage so we don't drop the edit
      // entirely. If quota's full at this point, MaxDB is the only
      // thing that would have rescued us — log so it's visible.
      try {
        _persistTripRaw(_currentTripId, envelopeJson);
      } catch (e) {
        if (e && (e.name === "QuotaExceededError" || (e.code && e.code === 22))) {
          console.warn("[Max] localStorage full and MaxDB unavailable — edit not persisted on this device. Reload to retry with MaxDB.");
          // v360.3 (#104): surface to the user. This is a silent-data-
          // loss state — every edit since the quota filled is being
          // dropped. Guarded by a session flag so we warn once per
          // tab, not on every save attempt (which would be a wall of
          // alerts as autoSave fires). Reload restarts the session
          // and re-arms the flag, so the user gets a fresh warning
          // if the underlying problem isn't fixed.
          if (!window._maxQuotaWarned && typeof maxAlert === "function") {
            window._maxQuotaWarned = true;
            maxAlert(
              "⚠ <strong>Your edits aren't being saved on this device.</strong><br><br>" +
              "Local storage is full and the IndexedDB fallback isn't available, " +
              "so changes you make to this trip won't persist when you reload.<br><br>" +
              "<strong>What to do:</strong><br>" +
              "• Sign in (⇄ in the header) — your trip syncs to the server immediately.<br>" +
              "• Or download a backup via <em>Export → Save as PDF</em> before reloading."
            );
          }
        } else {
          throw e;
        }
      }
    }
  }catch(e){
    console.warn("localSave failed:",e);
  }
}

function localLoad(tripId){
  if(_inIframe)return false;
  // v359.60.93: route through MaxDB.trip.readRaw so we pick up trips
  // that live in IndexedDB. Trip bodies overflow to IDB when
  // localStorage hits quota (or when MaxDB chooses IDB up-front for
  // large bodies). Before this, localLoad only checked localStorage,
  // so an IDB-only trip showed in the home-screen list (because the
  // index lives in localStorage and is fine) but tapping the card
  // did nothing — localLoad returned false, selectTrip exited
  // silently, and the user saw a dead button. Falling back to the
  // raw localStorage read keeps boot order safe: if MaxDB.trip isn't
  // wired up yet, we still have the original path.
  try {
    var raw = null;
    if (typeof MaxDB !== "undefined" && MaxDB.trip && typeof MaxDB.trip.readRaw === "function") {
      raw = MaxDB.trip.readRaw(tripId);
    }
    if (!raw) {
      raw = localStorage.getItem("max-trip-" + tripId);
    }
    if (raw) { restoreTrip(raw); return true; }
  } catch (e) {
    console.warn("localLoad failed:", e);
  }
  return false;
}

// v360.2: wisp helpers — Spark wisps are the user's possibilities captured
// throughout the trip's life (initial intent + later "what else might matter"
// captures). Storing them as structured records (not just notes text) lets
// Discovery know which are still unprocessed and feed them into the next
// LLM run. Without this, the Spark intake is a write-only journal — fix #1
// from the recursive-loop audit.
//
// Shape:
//   trip.brief.tripMeta.wisps = [
//     { id, text, capturedAt, processedAt, resultItemIds }
//   ]
// processedAt === null means "Max hasn't evaluated this yet."
//
// Legacy data: earlier builds wrote ✨-prefixed lines into
// trip.brief.tripMeta.notes (a single string). _wispMigrateLegacy reads
// those once, lifts each ✨-line into a structured wisp, and removes it
// from the notes blob so the data lives in one place going forward.
function _wispsArray(trip) {
  if (!trip) return [];
  if (!trip.brief) trip.brief = {};
  if (!trip.brief.tripMeta) trip.brief.tripMeta = {};
  if (!Array.isArray(trip.brief.tripMeta.wisps)) trip.brief.tripMeta.wisps = [];
  return trip.brief.tripMeta.wisps;
}
