  if (typeof MaxRoute !== "undefined" && trip && trip.id) {
    MaxRoute.navigate({ screen: MaxRoute.SCREENS.BRIEF, tripId: trip.id });
  }
  var _prevScroll = ov.scrollTop || 0;
  var _preserve = !!_tb._preserveScrollOnce;
  _tb._preserveScrollOnce = false;
