          // Place row — extract name, wiki desc, sights-here, activities.
          var nameEl = el.querySelector(".tb-act-name");
          var placeText = "";
          if (nameEl) {
            var nameSpan = nameEl.querySelector("span");
            placeText = nameSpan ? (nameSpan.textContent || "").trim() : (nameEl.textContent || "").trim();
          }
          // Stay-candidate hint via the role indicator's title attribute
