            // Activity row structure after PD.18/PD.24: first div = name, optional .tb-act-desc = description.
            var nameDiv = act.querySelector('div[style*="font-weight:600"]') || act.querySelector("div");
            var descDiv = act.querySelector(".tb-act-desc") || act.querySelector('div[style*="color:#666"]');
