    +   'function openLocalPlacePopup(canon,info,marker){'
    +     'if(!marker||!map)return;'
    +     'var state=getState();if(!state)return;'
    +     'var byKey=state._byKey||{};'
    +     'var selfRec=byKey[canon];'
    +     'var selfLat=selfRec?selfRec.lat:null,selfLng=selfRec?selfRec.lng:null;'
    +     'function distSq(aLat,aLng,bLat,bLng){'
    +       'if(aLat==null||bLat==null)return Infinity;'
    +       'var dLat=aLat-bLat,dLng=aLng-bLng;return dLat*dLat+dLng*dLng;'
    +     '}'
    +     'var hubs=[];'
    +     'Object.keys(byKey).forEach(function(k){'
    +       'if(k===canon)return;'
    +       'var h=byKey[k];'
    +       'if(!h.keep||h._isDayTrip)return;'
