    +     'var hubOptions=hubs.map(function(h){'
    +       'var sel=(h.key===currentHub)?"selected":"";'
    +       'return \'<option value="\'+esc(h.key)+\'" \'+sel+\'>\'+esc(h.place)+\'</option>\';'
    +     '}).join("");'
    +     'if(noHubs)hubOptions=\'<option value="">(no other kept stays)</option>\';'
    +     'var html=\'\''
    +       '+\'<div id="\'+popupId+\'" style="font-family:inherit;font-size:12.5px;min-width:200px;">\''
    +       '+\'<div style="font-weight:700;margin-bottom:6px;">\'+esc(info.place)+\'</div>\''
    +       '+\'<label style="display:flex;align-items:center;gap:6px;margin:4px 0;cursor:pointer;">\''
    +         '+\'<input type="radio" name="pm-mode" value="stay" \'+stayChecked+\' />\''
    +         '+\'<span>Stay the night</span>\''
    +       '+\'</label>\''
    +       '+\'<label style="display:flex;align-items:center;gap:6px;margin:4px 0;\'+(noHubs?\'opacity:0.55;cursor:not-allowed;\':\'cursor:pointer;\')+\'" \'+dtTitle+\'>\''
    +         '+\'<input type="radio" name="pm-mode" value="daytrip" \'+dtChecked+\' \'+dtDisabled+\' />\''
    +         '+\'<span>Day trip / On the way from</span>\''
    +         '+\'<select class="pm-hub-sel" \'+dtDisabled+\' style="font-family:inherit;font-size:12px;padding:2px 4px;">\'+hubOptions+\'</select>\''
    +       '+\'</label>\''
    +       '+\'<div style="display:flex;justify-content:flex-end;gap:6px;margin-top:8px;">\''
    +         '+\'<button type="button" class="pm-cancel" style="font-family:inherit;font-size:11.5px;padding:3px 10px;background:#eee;border:1px solid var(--c-border-strong);border-radius:4px;cursor:pointer;">Cancel</button>\''
    +         '+\'<button type="button" class="pm-save" style="font-family:inherit;font-size:11.5px;font-weight:600;padding:3px 10px;background:var(--c-primary);color:var(--c-on-dark);border:1px solid #144a86;border-radius:4px;cursor:pointer;">Save</button>\''
    +       '+\'</div>\''
    +     '+\'</div>\';'
    +     'try{marker.unbindPopup();}catch(_){}'
    +     'var popup=L.popup({maxWidth:280,autoClose:true,closeButton:true}).setLatLng(marker.getLatLng()).setContent(html);'
    +     'popup.openOn(map);'
    +     'setTimeout(function(){'
    +       'var root=document.getElementById(popupId);'
    +       'if(!root)return;'
    +       'var save=root.querySelector(".pm-save");'
    +       'var cancel=root.querySelector(".pm-cancel");'
    +       'var hubSel=root.querySelector(".pm-hub-sel");'
    +       'var radios=root.querySelectorAll(\'input[name="pm-mode"]\');'
    +       'function syncDisabled(){'
    +         'var v=root.querySelector(\'input[name="pm-mode"]:checked\');'
    +         'var isDT=v&&v.value==="daytrip";'
