    +         'try{var op=window.opener;if(op&&!op.closed&&typeof op._pmSetPlaceDayTrip==="function"){op._pmSetPlaceDayTrip(canon,mode==="daytrip",hub);}}catch(_){}'
    +         'map.closePopup(popup);'
    +       '});'
    +     '},0);'
    +   '}'
    +   'function renderMap(){'
    +     'if(typeof L==="undefined")return;'
    +     'if(!map){'
    +       'map=L.map("map",{zoomControl:true,scrollWheelZoom:true,attributionControl:false}).setView([46.8,8.2],6);'
    /* v353.2: this popup map (place-picker "Open in new window")
       was on Carto vector tiles. Switched to satellite to match
       the rest of the app. */
    +       'L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",{attribution:"© Esri",maxZoom:19}).addTo(map);'
    +       'L.tileLayer("https://{s}.basemaps.cartocdn.com/light_only_labels/{z}/{x}/{y}{r}.png",{opacity:1.0,maxZoom:19}).addTo(map);'
    +     '}'
    +     'var pts=getState();'
    +     'if(!pts){document.getElementById("ttl").textContent="Map — parent window closed";return;}'
          /* v354: include day-trip flags in the change signature so the
             popout repaints when the user toggles a place between stay
             and day trip in the parent window. v357: dropped startHint
             from the sig (no more route polyline / start-from). (No
             leading "+" — see unary-plus note above.) */
    +     'var sig=pts.map(function(p){return p.place+":"+(p.keep?1:0)+":"+(p.iconic?1:0)+":"+(p._isDayTrip?1:0)+":"+(p._dayTripHub||"");}).join("|")+"#"+(pts._region||"")+"~"+((pts._entryPoints||[]).length);'
    +     'if(sig===lastSig)return;'
    +     'lastSig=sig;'
    +     'var seen={};var bounds=[];'
    +     'pts.forEach(function(info){'
    +       'var k=pk(info);seen[k]=1;'
    +       'var sp=pinSpec(info);'  /* Round NC.X: dimensions from MaxMapPin.iconSpec */
    +       'var icon=L.divIcon({html:pinHtml(info),className:"",iconSize:sp.iconSize,iconAnchor:sp.iconAnchor,popupAnchor:sp.popupAnchor});'
    +       'var ll=[info.lat,info.lng];bounds.push(ll);'
    +       'if(markers[k]){markers[k].setIcon(icon);markers[k].setLatLng(ll);'
    +         'if(markers[k].getTooltip())markers[k].setTooltipContent(tooltipText(info));'
    +       '}else{'
    +         'var m=L.marker(ll,{icon:icon}).addTo(map);'
    +         'm.bindTooltip(tooltipText(info),{direction:"top",offset:[0,-10]});'
          /* v359.1.2: clicking a pin in the popout opens the day-trip
             popup LOCALLY in this window via openLocalPlacePopup. On
             Save we call window.opener._pmSetPlaceDayTrip so the
             parent's state mutates; the 600ms poll re-renders the
             pin colors. We no longer focus the parent — the popup is
             local now. Falls back to scrollOpenerToPlace only if
             local-popup setup throws. (No leading "+" — see
             unary-plus note above.) */
    +         '(function(name,marker){marker.on("click",function(){'
    +           'try{'
    +             'var state=getState();'
    +             'var info=state&&state._byKey&&state._byKey[pk(name)];'
    +             'if(info){openLocalPlacePopup(pk(name),info,marker);return;}'
    +           '}catch(_){}'
    +           'scrollOpenerToPlace(name);'
    +         '});})(info.place,m);'
    +         'markers[k]=m;'
    +       '}'
    +     '});'
    +     'Object.keys(markers).forEach(function(k){if(!seen[k]){try{map.removeLayer(markers[k]);}catch(_){}delete markers[k];}});'
          /* v357: main-route polyline removed from the popout window —
             matches the inline picker map. Sequencing is trip-view-only.
             byKey is still needed below for the day-trip spur lookup. */
    +     'var byKey=pts._byKey||{};'
          /* Day-trip spurs: dashed orange line from each kept day-trip\'s
             hub stay out to the day-trip place. Same colors/weights as
             the inline map for visual parity. (No leading "+" — see
             unary-plus note above.) */
    +     'Object.keys(spurs).forEach(function(k){try{map.removeLayer(spurs[k]);}catch(_){}delete spurs[k];});'
    +     'pts.forEach(function(info){'
    +       'if(!info._isDayTrip||!info._dayTripHub)return;'
    +       'var hub=byKey[pk(info._dayTripHub)];'
