    // comment on its own row so it doesn't sit between two +s.
    + '<script>'
    +   'window.addEventListener("error", function(e){'
    +     'var msg = "Popup error: " + (e && e.message ? e.message : "(unknown)") + " @ " + (e && e.filename ? e.filename : "?") + ":" + (e && e.lineno ? e.lineno : "?");'
    +     'try { if (window.opener && !window.opener.closed) window.opener.console.error("[Max view-larger popup]", msg, e && e.error); } catch(_){}'
    +     'try { document.body.insertAdjacentHTML("beforeend", \'<div style="position:fixed;left:10px;right:10px;bottom:10px;padding:10px 14px;background:#fee;border:1px solid #c44;border-radius:6px;color:#700;font-size:11px;font-family:monospace;z-index:9999;white-space:pre-wrap;word-break:break-word;">\' + msg.replace(/[&<>]/g, function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;"}[c];}) + \'</div>\'); } catch(_){}'
    +   '});'
    + '<\/script>'
    + '<script>(function(){'
    +   'function _logBack(tag, msg){'
