    +     'routeHalo = L.polyline(coords, {color: "#fff", weight: 7, opacity: 0.9, lineCap: "round"}).addTo(map);'
    +     'routeLine = L.polyline(coords, {color: "#1a5fa8", weight: 3, opacity: 1.0, dashArray: "1 8", lineCap: "round"}).addTo(map);'
    +   '}'
    +   'function _eraseRoute(){'
