    +     'else { _drawRoute(); rb.textContent = "Route ✓"; rb.classList.remove("off"); }'
    +     'try { localStorage.setItem("max-popup-route-off", routeOff ? "1" : "0"); } catch(_){}'
    +   '};'
    // FN.A.4: split pts into destinations and gateways. Destinations
    // group by name (round-trip same-city collapse); gateways render
    // as standalone white-bg pins with dashed connectors.
    /* NC.7: destPts excludes considered pts so they don't get grouped
       into pinGroups (which renders numbered destination pins). */
    +   'var destPts = pts.filter(function(p){ return p.kind !== "gateway" && p.kind !== "considered"; });'
    +   'var gatewayPts = pts.filter(function(p){ return p.kind === "gateway"; });'
    +   'var consideredPts = pts.filter(function(p){ return p.kind === "considered"; });'
