    +       'return \'<div style="margin-bottom:6px;"><div style="font-size:12px;font-weight:700;color:#222;">\'+role+\'</div><div style="font-size:11px;color:#777;">\'+dateLine+\'</div></div>\';'
    +     '}).join("");'
