    +     'var cicon = L.divIcon({html: chtml, className: "trip-popout-considered-pin", iconSize: csp.iconSize, iconAnchor: csp.iconAnchor, popupAnchor: csp.popupAnchor});'
    +     'var cm = L.marker([p.lat, p.lng], {icon: cicon, zIndexOffset: -100}).addTo(map);'
    +     'cm.bindTooltip(p.place + " \\u00b7 considered", {direction: "top", offset: [0, -csp.iconSize[1]/2]});'
    +   '});'
    // v353.2: focus on the active destination if one was open when
    // the popup launched, instead of always fitting all destinations.
    +   'var activePt = pts.filter(function(p){return p.isActive;})[0];'
    +   'if (activePt) {'
