function dismissIntro(permanent){
  _tb._introDismissed = true;
  if(permanent){
    try { localStorage.setItem("max-hide-trip-intro", "1"); } catch(e){}
  }
  var box = document.getElementById("tb-intro-box");
  if(box) box.style.display = "none";
}

function toggleChip(el){
  var c = el.dataset.chip;
  _tb.chips = _tb.chips || [];
  var idx = _tb.chips.indexOf(c);
  if(idx > -1) _tb.chips.splice(idx, 1);
  else _tb.chips.push(c);
  el.classList.toggle("on");
}

// Add a custom chip the user typed. Lives alongside presets in _tb.chips;
// the renderer knows to give it an × to remove since it's not in the preset
// list. Preserves the sentence and any entered anchors so we don't lose them
// on re-render.

function removeCustomChip(chipText){
  if (!chipText) return;
  // Unescape HTML entities that came back from data-attr style encoding
  var decoded = chipText.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&quot;/g,'"').replace(/&#39;/g,"'");
  _tb.chips = (_tb.chips||[]).filter(function(c){return c !== decoded;});
  // TM.6 (v330): sentence-mode branch removed (place-mode is the only
  // entry path; renderTripStep1Recognition is gone).
  var nm = document.getElementById("tb-place-name");
  if (nm) _tb.placeName = nm.value;
  var ctx = document.getElementById("tb-place-context");
  if (ctx) _tb.placeContext = ctx.value;
  renderTripStep1Place();
}

// Place-mode counterpart to addCustomChip — preserves placeName/placeContext
// instead of the sentence, then re-renders the place-mode Step 1.
function addCustomChipPlaceMode(){
  var inp = document.getElementById("tb-chip-add");
  if (!inp) return;
  var val = (inp.value || "").trim();
  if (!val) return;
  _tb.chips = _tb.chips || [];
  var already = _tb.chips.some(function(c){ return c.toLowerCase() === val.toLowerCase(); });
  if (!already) _tb.chips.push(val);
  inp.value = "";
  var nm = document.getElementById("tb-place-name");
  if (nm) _tb.placeName = nm.value;
  var ctx = document.getElementById("tb-place-context");
  if (ctx) _tb.placeContext = ctx.value;
  renderTripStep1Place();
  setTimeout(function(){
    var i = document.getElementById("tb-chip-add");
    if (i) i.focus();
  }, 50);
}

function saveRecognitionAndContinue(){
  // Save sentence, chips, anchors
  _tb.tripSentence = g("tb-sentence") ? g("tb-sentence").value.trim() : (_tb.tripSentence||"");
  _tb.anchors      = g("tb-anchors")  ? g("tb-anchors").value.trim()  : (_tb.anchors||"");

  // Build the intent that will feed the prompt
  var parts = [];
  if(_tb.tripSentence) parts.push(_tb.tripSentence);
  if(_tb.chips && _tb.chips.length) parts.push("Also interested in: " + _tb.chips.join(", "));
  _tb.intent = parts.join(". ");

  // Extract region from sentence — try multiple patterns
  var s = _tb.tripSentence || "";
  var m;
  // Pattern 0: new template — "Because I want to ..., I'm going to go to X"
  // Also handles "...I am going to X" and "...I am going to go to X"
  m = s.match(/i['’]?\s*(?:am|m)\s+going\s+to\s+(?:go\s+to\s+)?([^,\.;]+?)(?:\s*[,.;]|\s*$)/i);
  if(!m){
    // Pattern 0b: "going to go to X" anywhere (handles the double-'to' so we don't capture just "go")
    m = s.match(/going\s+to\s+go\s+to\s+([^,\.;]+?)(?:\s*[,.;]|\s*$)/i);
  }
  if(!m){
    // Pattern 1: "I want to go to X in order to..."
    m = s.match(/^\s*i\s+want\s+to\s+go\s+to\s+([^,\.;]+?)(?:\s+in\s+order\s+to|\s+to\s+|\s*[,.;]|\s*$)/i);
  }
  if(!m){
    // Pattern 2: "I want to go to X for..." / "I want to go to X,"
    m = s.match(/^\s*i\s+want\s+to\s+go\s+to\s+([^,\.;]+?)(?:\s+for\s+|\s*[,.;]|\s*$)/i);
  }
  if(!m){
    // Pattern 3: "going to X" / "travel to X" / "trip to X" — but exclude "going to go"
    m = s.match(/(?:going|traveling|travel|trip|heading)\s+to\s+(?!go\b)([^,\.;]+?)(?:\s+(?:in\s+order\s+to|to|for|because)|\s*[,.;]|\s*$)/i);
  }
  if(m && m[1]){
    _tb.region = m[1].trim();
  } else if(!_tb.region){
    // Fallback: use the whole sentence (truncated if long) as the region context
    _tb.region = s.length > 60 ? s.substring(0, 60).trim() + "\u2026" : s;
  }

  if(!_tb.tripSentence){
    maxAlert(_briefMissingFieldMsg());
    return;
  }

  renderTripBrief();
}

// Round NC.X: tailor the "you need to fill this in" message to what
// the user ACTUALLY left blank. Showing "Please describe where you
// want to go and what you want to do there" when the user has
// already filled in why-this-place reads as if Max isn't paying
// attention. Returns the most-specific message the empty-field
// set warrants.
function _briefMissingFieldMsg(){
  function _read(id){ var el = g(id); return (el && el.value ? el.value : "").trim(); }
  // Where: placeName field (the new single-page brief) OR region OR
  // tripSentence (legacy single-line form).
  var hasPlace = !!(
    (_tb.placeName || "").trim() ||
    (_tb.region    || "").trim() ||
    _read("tb-place-name") ||
    _read("tb-region")
  );
  // Why: either of the two why fields (whySpecifically / whyGenerally)
  // OR the legacy placeContext / tripSentence as a fallback signal.
  var hasWhy = !!(
    (_tb.whySpecifically || "").trim() ||
    (_tb.whyGenerally    || "").trim() ||
    (_tb.placeContext    || "").trim() ||
    (_tb.tripSentence    || "").trim() ||
    _read("tb-why-specifically") ||
    _read("tb-why-generally")
  );
  if (!hasPlace && !hasWhy) {
    return "Tell me where you want to go and a little about what's drawing you there.";
  }
  if (!hasPlace) {
    return "Tell me where you want to go.";
  }
  if (!hasWhy) {
    return "Tell me a little about what's drawing you there.";
  }
  // All present (caller shouldn't have reached this branch, but keep
  // a friendly fallback in case the validator and the message helper
  // disagree).
  return "Please double-check the trip details — something's missing.";
}



// Update _tb.familiarity and the chip's "on" class in place, without re-rendering
// the whole overlay (which would reset scroll position).
function _tbPickFamiliarity(id){
  _tb.familiarity = id;
  // Also persist textarea values so they don't get lost if the overlay DOES re-render later
  var _ta = document.getElementById("tb-sentence");
  if(_ta) _tb.tripSentence = _ta.value;
  var _anc = document.getElementById("tb-anchors");
  if(_anc) _tb.anchors = _anc.value;
  // Update chip classes — all tb-fam-chip elements on the current overlay
  var chips = document.querySelectorAll(".tb-fam-chip");
  for (var i = 0; i < chips.length; i++){
    var chip = chips[i];
    var chipId = chip.getAttribute("data-fam-id");
    chip.classList.toggle("on", chipId === id);
  }
}

function toggleEntryExit(which, isFixed){
  if(which === "entry") _tb.entryFixed = isFixed;
  else _tb.exitFixed = isFixed;
  // Update button classes
  var row = document.getElementById(which + "-toggles");
  if(row){
    var spans = row.querySelectorAll(".tb-toggle");
    spans[0].classList.toggle("on", isFixed);
    spans[1].classList.toggle("on", !isFixed);
  }
  // Update placeholder of input
  var inp = document.getElementById("tb-" + (which === "entry" ? "entry" : "exit"));
  if(inp){
    if(which === "entry") inp.placeholder = isFixed ? "e.g. Zurich \u2014 tickets already booked" : "e.g. Probably Zurich or Geneva, open to what fits";
    else inp.placeholder = isFixed ? "e.g. Geneva \u2014 tickets already booked" : "e.g. Same place, or wherever makes sense";
  }
}

