      var ph = (typeof MaxBuild.phase === "function" && MaxBuild.phase()) || "build:start";
      var _bmode = (typeof MaxBuild.mode === "function" && MaxBuild.mode()) || null;
      // PD.394: the build MODE names the operation, decisively.
      //   "candidate-first" = the Discovery→trip build → determining the route.
      //   "activity-first"  = the after-upload Discovery build → finding more places.
      // This replaces the hasRoute heuristic, which couldn't tell the
      // two apart during the build (destinations don't exist yet in
      // either). The user's exact copy for each.
      if (_bmode === "candidate-first") {
        _setBanner("Max is determining your route…",
          "Max will tell you when that\u2019s done.");
        return;
      }
      if (_bmode === "activity-first" && (ph === "build:enhance-start" || ph === "build:reconcile-done" || ph === "build:primary-done")) {
        _setBanner("Max is looking for other places that you might want to consider…",
          "Max will tell you when that\u2019s done.");
        return;
      }
      var hasRoute = (typeof trip !== "undefined" && trip
        && Array.isArray(trip.destinations) && trip.destinations.length > 0);
      if (ph === "build:start") {
        _setBanner("Max is working — finding places…",
          "Your own list is already on screen; everything Max adds appears around it.");
      } else if (ph === "build:primary-done") {
        _setBanner("Organizing the list…", "Sections, stays, and your night counts.");
      } else if (ph === "build:reconcile-done") {
        _setBanner("Placing your sights into sections…");
      } else {
        // PD.394: this is the AFTER-UPLOAD Discovery build — Max is
        // looking for additional places around the list you gave it.
        // (The "Max is determining your route" copy belongs to the
        // SEPARATE Discovery→trip transition, set explicitly there.)
        // The user's exact words.
        _setBanner("Max is looking for other places that you might want to consider…",
          "Max will tell you when that\u2019s done.");
      }
