  var distKm = 0;
  if (lat != null && lng != null
      && typeof hubDest.lat === "number" && typeof hubDest.lng === "number"
      && typeof _fqHaversineKm === "function") {
    distKm = Math.round(_fqHaversineKm(hubDest.lat, hubDest.lng, lat, lng));
  }
  var chip = {
    place: placeName,
    country: hubDest.country || "",
    lat: lat,
    lng: lng,
    whyItFits: "",
    attachedEvents: [],
    sourceNights: 1,
    absorbedFromHub: hubDest.place,
    distKm: distKm,
    clusteredAt: new Date().toISOString(),
    manuallyAdded: true
  };
